// Scores file lists against truth.json twice: full (baseline-comparable) and nav (truth minus non-navigation files).
import { readFileSync } from 'node:fs';
import path from 'node:path';
import { CASES } from './materialize.mjs';
import { fileMatch } from '../scripts/src/analysis/bench-score.mjs';

// Data, not code: translations, tests/specs, mocks/fixtures are found by reading siblings, not by navigating.
export const NON_NAV = [
  /(^|\/)(i18n|locales?|translations?|lang)\//i,
  /\.(spec|test)\.[^/]+$/i,
  /(^|\/)__mocks__\//,
  /(^|\/)(mocks?|fixtures?)\//i,
  /\.(mocks?|fixtures?)\.[^/]+$/i,
];
export const isNonNav = (p) => NON_NAV.some((re) => re.test(p));

export function loadTruth(id) {
  const t = JSON.parse(readFileSync(path.join(CASES, id, 'truth.json'), 'utf8'));
  const nav = t.truth.filter((p) => !isNonNav(p));
  return { full: t.truth, nav, removed: t.truth.length - nav.length, root: t.root ?? '' };
}

export function scoreFiles(files, truth) {
  const pick = ({ named, correct, truth: n, precision, recall }) => ({ named, correct, truth: n, precision, recall });
  return { full: pick(fileMatch(files, truth.full)), nav: truth.nav.length ? pick(fileMatch(files, truth.nav)) : null };
}

if (process.argv[1] === new URL(import.meta.url).pathname) {
  const ids = process.argv.slice(2);
  for (const id of ids) { const t = loadTruth(id); console.log(id, `truth ${t.full.length}`, `nav ${t.nav.length}`, `removed ${t.removed}`); }
}
// Extracts a case's base commit into <dir>/repo (cached under repos/<id>/). Parses scaffold.sh; never runs it.
import { execFileSync } from 'node:child_process';
import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const HERE = path.dirname(fileURLToPath(import.meta.url));
export const CASES = path.resolve(HERE, '../common/core/cases');
// Outside the plugin tree: `claude plugin eval` refuses a plugin directory over 20,000 entries.
export const REPOS = path.resolve(HERE, '../../../../ambicode-evals-assets/nav-repos');

// scaffold.sh's relative path is stale (archive moved one level deeper); only the side name and sha are trusted.
export function parseScaffold(id) {
  const file = path.join(CASES, id, 'scaffold.sh');
  const text = readFileSync(file, 'utf8');
  const side = /benchmarks\/([\w-]+)'/.exec(text)?.[1];
  const sha = /git -C "\$CACHE" archive '([0-9a-f]{40})'/.exec(text)?.[1];
  if (!side || !sha) throw new Error(`scaffold.sh of ${id}: no side or sha`);
  const sideDir = path.resolve(HERE, '../../../../ambicode-evals-assets/benchmarks', side);
  return { side, sha, sideDir, cache: path.join(sideDir, '.git') };
}

/** Returns the repo path; reuses the cached extraction when it exists. */
export async function materialize(id, dir = path.join(REPOS, id)) {
  const repo = path.join(dir, 'repo');
  const cached = path.join(REPOS, id, 'repo');
  if (existsSync(path.join(cached, '.ambicode', 'config.yaml'))) {
    return repo;
  }
  const { sha, cache } = parseScaffold(id);
  // git add/commit are denied here and map needs a tracked index, so the checkout is a detached worktree of the cache.
  mkdirSync(path.dirname(repo), { recursive: true });
  execFileSync('git', ['--git-dir', cache, 'worktree', 'add', '--detach', repo, sha], { stdio: 'ignore' });
  mkdirSync(path.join(repo, '.ambicode'), { recursive: true });
  // The archived config is schemaVersion 1; today's loader wants 5, so a minimal current one is written (root ".", all files searchable).
  const { CONFIG_HEAD } = await import('../../../src/testing/fixtures/route-fixture.ts');
  writeFileSync(path.join(repo, '.ambicode/config.yaml'), `${CONFIG_HEAD}\n  - { id: app, root: ".", paths: [], ecosystem: { languages: [typescript], frameworks: [], packageManager: null } }\n`);
  return repo;
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const [id, dir] = process.argv.slice(2);
  if (!id || !dir) { console.error('usage: materialize.mjs <id> <dir>'); process.exit(2); }
  console.log(await materialize(id, dir));
}

import path from 'node:path';
import { buildModuleTree, tokensOf } from '#modules/context/context';
import { harvest } from '#modules/search/harvest';
import { wordsOf } from '#modules/search/map';
import type { Git } from '#platform/git/git';
import { NAVIGATOR_FEATURES_FILE } from '#types/defaults';
import type { FileSystem } from '#types/platform/ports';
import { COMMON_NAMES } from '#types/modules/search';
import { AmbicodeError } from '#util/errors';
import { isSearchable, isTestPath } from '#util/path-classes';

/** User-set budget for the whole file (2026-10-17, was 2000), counted as chars/4 like every other context budget. */
export const FEATURES_BUDGET_TOKENS = 2500;
/** 30 x 80 = 2400 leaves the file under the budget with no trimming. */
export const MAX_FEATURES = 30;
const ENTRY_TOKENS = 80;
const MAX_TERMS = 6;
const ABSENT = '-';

export interface FeatureEntry { feature: string; terms: string[]; files: string[]; deps: string[]; models: string[] }

const LINE = /^## ([^|]+?) \| terms: ([^|]*?) \| files: ([^|]*?) \| deps: ([^|]*?) \| models: ([^|]*)$/;
const list = (value: string): string[] => (value === ABSENT ? [] : value.split(',').map((item) => item.trim()));
const cell = (items: readonly string[]): string => (items.length === 0 ? ABSENT : items.join(','));

export function parseFeatures(text: string): FeatureEntry[] {
  return text.trimEnd().split('\n').map((line, index) => {
    const match = LINE.exec(line);
    if (match === null) throw new AmbicodeError('navigator-features-invalid', `features line ${index + 1} does not match "## <feature> | terms: | files: | deps: | models:".`, { field: NAVIGATOR_FEATURES_FILE });
    return { feature: match[1]!, terms: list(match[2]!), files: list(match[3]!), deps: list(match[4]!), models: list(match[5]!) };
  });
}

export const renderEntry = (entry: FeatureEntry): string => `## ${entry.feature} | terms: ${cell(entry.terms)} | files: ${cell(entry.files)} | deps: ${cell(entry.deps)} | models: ${cell(entry.models)}`;

/** A comma, pipe or newline in a path would split the field it sits in. */
const representable = (file: string): boolean => !/[,|\n]/.test(file);

/**
 * One feature per directory module of the source tree (the same cluster `context tree` uses, capped at MAX_FEATURES); directories under 3 files fold into the parent.
 * Terms are the words of file stems and declared names, rarest across features first: a word every feature has says nothing.
 * deps and models stay empty: no language-neutral way to read them from the tree.
 */
export function buildSeed(allFiles: readonly string[], names: ReadonlyMap<string, readonly string[]>): FeatureEntry[] {
  const files = allFiles.filter((file) => isSearchable(file) && !isTestPath(file) && representable(file));
  const { modules } = buildModuleTree(files, { roots: [], maxModules: MAX_FEATURES });
  // A file belongs to its deepest module, so a parent lists only what its submodules do not.
  const sources = new Map(modules.map((module) => [module.path, [] as string[]]));
  for (const file of [...files].sort()) {
    const owner = modules.filter((module) => file.startsWith(`${module.path}/`)).sort((a, b) => b.depth - a.depth)[0];
    if (owner !== undefined) sources.get(owner.path)!.push(file);
  }
  const wordsOfFile = (file: string): string[] => [...wordsOf(path.posix.basename(file, path.posix.extname(file))), ...(names.get(file) ?? []).flatMap(wordsOf)];
  const perModule = new Map(modules.map((module) => [module.path, wordsOfModule(sources.get(module.path)!, wordsOfFile)]));
  const spread = new Map<string, number>();
  for (const words of perModule.values()) for (const word of words.keys()) spread.set(word, (spread.get(word) ?? 0) + 1);
  const shortNames = modules.map((module) => module.path.split('/').at(-1)!);
  return modules.map((module, at) => {
    const feature = shortNames.filter((name) => name === shortNames[at]).length > 1 ? module.path : shortNames[at]!;
    const own = new Set(wordsOf(module.path));
    const terms = [...perModule.get(module.path)!]
      .filter(([word]) => !own.has(word) && word.length >= 3 && !COMMON_NAMES.has(word))
      .sort((a, b) => spread.get(a[0])! - spread.get(b[0])! || b[1] - a[1] || a[0].localeCompare(b[0]))
      .slice(0, MAX_TERMS)
      .map(([word]) => word);
    const head = { feature, terms, deps: [], models: [] };
    const kept: string[] = [];
    // Files come after terms in the line, so they fill whatever the 80-token cap leaves.
    for (const file of sources.get(module.path)!) {
      if (tokensOf(`${renderEntry({ ...head, files: [...kept, file] })}\n`) > ENTRY_TOKENS) break;
      kept.push(file);
    }
    return { ...head, files: kept };
  }).filter((entry) => entry.files.length > 0).sort((a, b) => a.files[0]!.localeCompare(b.files[0]!));
}

function wordsOfModule(files: readonly string[], wordsOfFile: (file: string) => string[]): Map<string, number> {
  const counts = new Map<string, number>();
  for (const file of files) for (const word of new Set(wordsOfFile(file))) counts.set(word, (counts.get(word) ?? 0) + 1);
  return counts;
}

export interface SeedOutcome { path: string; entries: number; tokens: number }

/** An existing features.md with content holds refinements the seed cannot rebuild, so it is refused, never merged or replaced. */
export async function seedFeatures(fs: FileSystem, git: Git, root: string): Promise<SeedOutcome> {
  const target = path.join(root, NAVIGATOR_FEATURES_FILE);
  if ((await fs.exists(target)) && (await fs.readText(target)).trim() !== '') {
    throw new AmbicodeError('navigator-features-exist', `${NAVIGATOR_FEATURES_FILE} already has content; the seed does not overwrite it.`, { field: NAVIGATOR_FEATURES_FILE, details: ['Delete the file to seed again.'] });
  }
  const files = (await git.listFiles(null)).filter((file) => isSearchable(file) && !isTestPath(file));
  const names = new Map<string, string[]>();
  for (const declaration of await harvest(fs, root, files)) names.set(declaration.path, [...(names.get(declaration.path) ?? []), declaration.name]);
  const entries = buildSeed(files, names);
  const text = `${entries.map(renderEntry).join('\n')}\n`;
  const tokens = tokensOf(text);
  if (tokens > FEATURES_BUDGET_TOKENS) throw new AmbicodeError('navigator-features-too-large', `seed is ~${tokens} tokens, over ${FEATURES_BUDGET_TOKENS}.`, { field: NAVIGATOR_FEATURES_FILE });
  await fs.mkdirp(path.dirname(target));
  await fs.writeText(target, text);
  return { path: NAVIGATOR_FEATURES_FILE, entries: entries.length, tokens };
}
import path from 'node:path';
import { DECLARATION_PATTERNS } from '#types/modules/ecosystems';
import { MAX_SNAPSHOT_FILE_BYTES } from '#types/defaults';
import type { Git } from '#platform/git/git';
import type { FileSystem } from '#types/platform/ports';
import { COMMON_NAMES, type Declaration } from '#types/modules/search';

const MIN_NAME = 3;
const EXPORT_LINE = /^\s*export\b/;
const HAS_EXPORT = /^\s*export\b/m;
const KINDS = ['function', 'class', 'interface', 'type', 'enum', 'namespace', 'const', 'let', 'var', 'def', 'fn', 'func'];

function kindOf(line: string): string {
  const keyword = KINDS.find((candidate) => new RegExp(`\\b${candidate}\\b`).test(line));
  return keyword === 'def' || keyword === 'fn' || keyword === 'func' ? 'function' : (keyword ?? 'member');
}

/**
 * Declarations the shared patterns find in the given files. A file with any `export` line counts its exported
 * declarations only (what another file can reach); a file without one (Python, Go) counts every declaration.
 * `declarations` is the number of files declaring the name, so overloads in one file do not collide.
 */
export async function harvest(fs: FileSystem, root: string, files: readonly string[]): Promise<Declaration[]> {
  const patterns = DECLARATION_PATTERNS.map((pattern) => new RegExp(pattern.source, `${pattern.flags.replace('g', '')}g`));
  const found: Omit<Declaration, 'declarations'>[] = [];
  for (const file of files) {
    let text: string;
    try {
      const absolute = path.join(root, file);
      if ((await fs.stat(absolute)).size > MAX_SNAPSHOT_FILE_BYTES) continue;
      text = await fs.readText(absolute);
    } catch {
      continue;
    }
    const exportOnly = HAS_EXPORT.test(text);
    const seen = new Set<string>();
    text.split(/\r?\n/).forEach((line, index) => {
      if (exportOnly && !EXPORT_LINE.test(line)) return;
      for (const pattern of patterns) {
        pattern.lastIndex = 0;
        for (const match of line.matchAll(pattern)) {
          const name = match[1];
          if (name === undefined || name.length < MIN_NAME || COMMON_NAMES.has(name) || seen.has(`${name}:${index}`)) continue;
          seen.add(`${name}:${index}`);
          found.push({ name, kind: kindOf(line), path: file, line: index + 1 });
        }
      }
    });
  }
  const filesPerName = new Map<string, Set<string>>();
  for (const declaration of found) filesPerName.set(declaration.name, (filesPerName.get(declaration.name) ?? new Set()).add(declaration.path));
  return found.map((declaration) => ({ ...declaration, declarations: filesPerName.get(declaration.name)!.size }));
}

/** Project-wide declarations of the names: the files containing each as a whole word, harvested. Used by `refs` and the review bundle. */
export async function declarationsOf(git: Git, fs: FileSystem, names: readonly string[], pathspec: string | null): Promise<Declaration[]> {
  const files = await git.grepWords(names, pathspec);
  return (await harvest(fs, git.options.repositoryRoot, files)).filter((declaration) => names.includes(declaration.name));
}
