describe('importsOf', () => {
  it('reads ES imports across lines, re-exports, side-effect, dynamic and destructured require', () => {
    const text = [
      "import def, { a as b, type C } from './x';",
      "import * as ns from \"../y\";",
      "import {\n  d,\n  e,\n} from 'pkg/deep';",
      "export { f } from './z';",
      "import './side';",
      "const lazy = () => import('./lazy');",
      "const { g, h: i } = require('./cjs');",
