    const bySpec = new Map(importsOf(text).map((entry) => [entry.spec, entry.names]));
    assert.deepEqual(bySpec.get('./x'), ['a', 'C', 'default']);
    assert.deepEqual(bySpec.get('../y'), ['*']);
    assert.deepEqual(bySpec.get('pkg/deep'), ['d', 'e']);
    assert.deepEqual(bySpec.get('./z'), ['f']);
    assert.deepEqual(bySpec.get('./side'), []);
    assert.deepEqual(bySpec.get('./lazy'), []);
