const md = readFileSync(path.join(ROOT, 'agents/navigator.md'), 'utf8');
const [, fm, body] = /^---\n([\s\S]*?)\n---\n([\s\S]*)$/.exec(md);
const tools = /^tools:\s*(.*)$/m.exec(fm)[1].split(/,\s*/);
const args = ['-p', '--model', 'claude-sonnet-5-5', '--effort', 'low', '--output-format', 'stream-json', '--verbose', '--no-session-persistence', '--setting-sources', '', '--strict-mcp-config', '--max-budget-usd', '0.5', '--permission-mode', 'dontAsk', '--disallowedTools', 'Edit', 'Write', 'NotebookEdit',
  '--agents', JSON.stringify({ navigator: { description: 'navigator', prompt: body.trim(), tools, model: 'sonnet' } }), '--agent', 'navigator', '--allowedTools', ...tools];
const run = (cwd, input) => new Promise((resolve) => { const p = spawn('claude', args, { cwd, env: { ...process.env, CLAUDE_CODE_DISABLE_CLAUDE_MDS: '1' } }); let out = ''; p.stdout.on('data', (d) => { out += d; }); p.on('close', () => resolve(out)); p.stdin.end(input); });

const rows = rd('phase1.jsonl').filter((r) => r.matched.length);
await Promise.all(rows.map(async (r) => {
  const repo = path.join(REPOS, r.id, 'repo'), ticket = ticketOf(r.id), truth = loadTruth(r.id);
  const arms = { control: navigatorInput(ticket, dry[r.id].ranked, []), notes: navigatorInput(ticket, r.ranked, [], r.notes) };
  for (const [arm, input] of Object.entries(arms)) {
    const out = await run(repo, input);
    writeFileSync(path.join(HERE, `raw-p2-${arm}-${r.id}.jsonl`), out);
    const ev = out.split('\n').filter(Boolean).map((l) => { try { return JSON.parse(l); } catch { return null; } }).filter(Boolean);
