p='evals/navigator/run.test.mjs'
s=open(p).read()
s=s.replace("plan, ticketOf } from './lib.mjs';","plan, ticketOf, trackedRows } from './lib.mjs';\nimport { summary } from '../scripts/track.mjs';")
i=s.rstrip().rfind('});')
add="""
  const sc = (full, nav) => ({ full: { named: 9, correct: 5, truth: 34, precision: 0.5, recall: full }, nav: { named: 9, correct: 5, truth: 19, precision: 0.5, recall: nav } });
  const raw = (arm, run, scores, cost = 0.1) => ({ case: 'fe-vs-1-investigate', arm, run, cost, turns: 9, duration_ms: 20000, tools: { Grep: 2, Read: 1 }, scores });
  const ctx = { at: () => '2026-10-17T00:00:00.000Z', model: 'm', effort: 'low', plugin: '0.6.0' };

  it('tracked rows: one per case and arm, navigator is the plugin arm, score is full recall, ids and numbers only', () => {
    const rows = trackedRows([raw('navigator', 1, sc(0.2, 0.4), 0.1), raw('navigator', 2, sc(0.4, 0.6), 0.3), raw('bare', 1, sc(0.1, 0.1))], ctx);
