  it('creates a file whose every line parses and names each feature folder', async () => {
    await rm(featuresPath(), { force: true });
    await seed();
    const text = await readFile(featuresPath(), 'utf8');
    const lines = text.trimEnd().split('\n');
    const entries = parseFeatures(text);
    assert.equal(entries.length, lines.length);
    assert.ok(entries.length >= 5);
    for (const feature of ['customers', 'invoices', 'payments', 'notifications', 'reports']) {
      const entry = entries.find((candidate) => candidate.feature === feature);
