    const text = await readFile(featuresPath(), 'utf8');
    assert.ok(tokensOf(text) <= FEATURES_BUDGET_TOKENS, `${tokensOf(text)} tokens`);
    for (const line of text.trimEnd().split('\n')) assert.ok(tokensOf(`${line}\n`) <= 80, line);
  });

  it('refuses to overwrite a file with content and leaves it untouched', async () => {
    await mkdir(path.dirname(featuresPath()), { recursive: true });
    await writeFile(featuresPath(), '## mine | terms: x | files: a.ts | deps: - | models: -\n');
    await assert.rejects(seed(), (error: { code?: string }) => error.code === 'navigator-features-exist');
    assert.equal(await readFile(featuresPath(), 'utf8'), '## mine | terms: x | files: a.ts | deps: - | models: -\n');
  });

  it('seeds over a file that is empty or only whitespace', async () => {
    await writeFile(featuresPath(), '\n  \n');
    await seed();
    assert.ok(parseFeatures(await readFile(featuresPath(), 'utf8')).length > 0);
  });
});

describe('parseFeatures', () => {
  it('rejects a line that is not in the entry format', () => {
    assert.throws(() => parseFeatures('## a | terms: x | files: y\n'), /features line 1/);
    assert.throws(() => parseFeatures('# title\n'), /features line 1/);
  });
});

