    assert.deepEqual(entry!.files, ['src/customers/model.js', 'src/customers/service.js', 'src/customers/segments.js']);
    assert.deepEqual(entry!.deps, ['Core Location Service', 'auth']);
    assert.deepEqual(entry!.models, ['Organization', 'user', 'location']);
  });

  it('merges by file overlap into a learned entry under another name, but never into a seed entry', async () => {
    await learn(USER_MGMT);
    const outcome = await learn('## accounts | terms: signup | files: src/customers/service.js,src/payments/index.js | deps: x | models: y');
    const entries = await read();
    assert.equal(outcome.merged, 1);
    assert.equal(entries.some((entry) => entry.feature === 'accounts'), false);
    assert.ok(entries.find((entry) => entry.feature === 'user management')!.files.includes('src/payments/index.js'));
    const second = await learn('## shop | terms: cart | files: src/payments/index.js | deps: - | models: -');
    assert.equal(second.merged, 1, 'overlap with the learned entry, not with the payments seed entry');
  });

  it('absorbs the seed entry whose files a learned entry now owns, and trims the ones it shares partly', async () => {
    const seeded = await read();
    const customers = seeded.find((entry) => entry.feature === 'customers')!;
    await learn(`## people | terms: crm | files: ${customers.files.join(',')} | deps: db | models: customer`);
    const entries = await read();
    assert.equal(entries.some((entry) => entry.feature === 'customers'), false);
    assert.ok(entries.some((entry) => entry.feature === 'people'));
    await seed();
    await learn(USER_MGMT);
    const partly = (await read()).find((entry) => entry.feature === 'customers')!;
    assert.ok(partly.files.length > 0 && !partly.files.includes('src/customers/service.js') && !partly.files.includes('src/customers/segments.js'));
  });

  it('drops dead paths, counts them, and ignores a proposal with no live file', async () => {
    const outcome = await learn('## user management | terms: migration | files: src/customers/service.js,src/gone/old.js | deps: a | models: b');
    assert.equal(outcome.droppedPaths, 1);
    assert.deepEqual((await read())[0]!.files, ['src/customers/service.js']);
    const none = await learn('## ghost | terms: boo | files: src/gone/old.js | deps: a | models: b');
    assert.deepEqual([none.added, none.droppedPaths], [0, 1]);
    assert.equal((await read()).some((entry) => entry.feature === 'ghost'), false);
  });

  it('is idempotent: the same learn twice gives the same bytes', async () => {
    await learn(USER_MGMT);
    const first = await readFile(featuresPath());
    const outcome = await learn(USER_MGMT);
    assert.ok(first.equals(await readFile(featuresPath())));
    assert.equal(outcome.merged, 1);
  });

  it('rejects malformed input and leaves the file byte-identical', async () => {
    const before = await readFile(featuresPath());
    await assert.rejects(learn(`${USER_MGMT}\n## broken | terms: x | files: y`), /entry line 2/);
    await assert.rejects(learn('  \n'), (error: { code?: string }) => error.code === 'navigator-learn-invalid');
    assert.ok(before.equals(await readFile(featuresPath())));
  });

  it('creates the file when none exists', async () => {
    await rm(featuresPath());
    await learn(USER_MGMT);
    assert.equal((await read()).length, 1);
  });

  it('cuts an entry to ENTRY_TOKENS, dropping its oldest items', async () => {
    const many = Array.from({ length: 40 }, (_, index) => `term${index}`).join(',');
    await learn(`## wide | terms: ${many} | files: src/customers/service.js | deps: a | models: b`);
    const [entry] = await read();
    assert.ok(tokensOf(`${renderEntry(entry!)}\n`) <= ENTRY_TOKENS);
    assert.equal(entry!.terms[0], 'term0');
    assert.deepEqual([entry!.files.length, entry!.deps.length, entry!.models.length], [1, 1, 1]);
  });

  it('evicts seed-only entries from the bottom first, then learned ones, at 30 entries', async () => {
    const lines = Array.from({ length: MAX_FEATURES + 2 }, (_, index) => `## learned${index} | terms: t | files: src/app.js | deps: d | models: m`);
    await writeFile(featuresPath(), `${lines.slice(0, MAX_FEATURES).join('\n')}\n## seedy | terms: x | files: src/config.js | deps: - | models: -\n`.replace('learned0 |', 'learned0 |'));
    // 31 entries on disk is over the cap; one learn trims to 30 and the seed-only entry goes first.
    const outcome = await learn('## fresh | terms: f | files: src/flags.js | deps: d | models: m');
    const entries = await read();
    assert.equal(entries.length, MAX_FEATURES);
    assert.equal(outcome.evicted, 2);
    assert.equal(entries[0]!.feature, 'fresh');
    assert.equal(entries.some((entry) => entry.feature === 'seedy'), false);
    assert.equal(entries.at(-1)!.feature, `learned${MAX_FEATURES - 2}`);
  });

  it('evicts at the token limit', async () => {
    const pad = (index: number) => `## learned${index} | terms: ${'w'.repeat(40)},${'v'.repeat(40)} | files: src/app.js | deps: ${'d'.repeat(60)} | models: m`;
    const lines = Array.from({ length: 24 }, (_, index) => pad(index));
    assert.ok(tokensOf(`${lines.join('\n')}\n`) > FEATURES_BUDGET_TOKENS - 100, 'fixture lines must nearly fill the budget');
    await writeFile(featuresPath(), `${lines.join('\n')}\n`);
    const outcome = await learn(`## fresh | terms: ${'f'.repeat(300)} | files: src/flags.js | deps: d | models: m`);
    const text = await readFile(featuresPath(), 'utf8');
    assert.ok(tokensOf(text) <= FEATURES_BUDGET_TOKENS);
    assert.ok(outcome.evicted >= 1);
    assert.match(text.split('\n')[0]!, /^## fresh /);
  });

  it('motivating case: "migration" matches nothing before the learn and the intended entry after it', async () => {
    const prompt = 'fix modal for location for user migration';
    assert.deepEqual(matching(await read(), prompt), []);
    await learn(USER_MGMT);
    assert.deepEqual(matching(await read(), prompt), ['user management']);
    assert.deepEqual(matching(await read(), 'migration of the nightly job'), ['user management']);
  });
});
