// Navigator eval runner, separate from the plugin eval suite. See evals/navigator/README.md.
import { spawnSync } from 'node:child_process';
import { appendFileSync, cpSync, copyFileSync, existsSync, mkdirSync, readdirSync, readFileSync, realpathSync, writeFileSync } from 'node:fs';
import { createHash } from 'node:crypto';
import os from 'node:os';
import path from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { parseArgs } from 'node:util';
import { caseId, countTools, encodeProjectDir, featuresStats, filesBlock, mayLaunch, plan, ticketOf, trackedRows } from './lib.mjs';
import { readHistory, summary } from '../scripts/track.mjs';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const PLUGIN = path.resolve(HERE, '../..');
const env = process.env;
const { values: a } = parseArgs({
  options: {
    cases: { type: 'string' }, order: { type: 'string' }, arm: { type: 'string', default: 'navigator' },
    runs: { type: 'string', default: '1' }, 'max-cost-usd': { type: 'string' }, 'max-budget-usd': { type: 'string', default: '0.5' },
    bench: { type: 'string', default: env.NAV_BENCH }, 'cases-dir': { type: 'string', default: env.NAV_CASES },
    results: { type: 'string', default: env.NAV_RESULTS }, prompts: { type: 'string', default: env.NAV_PROMPTS },
    import: { type: 'boolean', default: false }, history: { type: 'string', default: path.join(PLUGIN, 'evals/history.jsonl') },
    scorer: { type: 'string', default: env.NAV_SCORER ?? path.join(PLUGIN, 'archive/evals/nav/score.mjs') },
  },
});
const need = (k) => { if (!a[k]) { console.error(`missing --${k}`); process.exit(2); } return a[k]; };
const MODEL = 'claude-sonnet-5-5';
const EFFORT = 'low';
const PLUGIN_VERSION = JSON.parse(readFileSync(path.join(PLUGIN, 'package.json'), 'utf8')).version;

// The bench and truth are NDA assets outside the repo; a machine without them gets one line, not a stack.
const requireAsset = (label, p) => { if (!existsSync(p)) { console.error(`navigator eval: ${label} not found at ${p} (NDA assets are not on this machine)`); process.exit(2); } };

// Appends to the suite history that `npm run evals` writes and refreshes its history.md.
function track(raw, at) {
  const out = trackedRows(raw, { at, model: MODEL, effort: EFFORT, plugin: PLUGIN_VERSION });
  appendFileSync(a.history, out.map((r) => `${JSON.stringify(r)}\n`).join(''));
  writeFileSync(path.join(path.dirname(a.history), 'history.md'), summary(readHistory(a.history)));
  for (const r of out) console.log(`tracked ${r.arm} ${r.case} recall ${r.score} $${r.costUsd} -> ${path.relative(PLUGIN, a.history)}`);
}

if (a.import) {
  const results = path.resolve(need('results'));
  requireAsset('results', path.join(results, 'history.jsonl'));
  const raw = readFileSync(path.join(results, 'history.jsonl'), 'utf8').split('\n').filter(Boolean).map((l) => JSON.parse(l))
    .filter((r) => !a.cases || a.cases.split(',').map(caseId).includes(r.case));
  const dayOf = (r) => `${readdirSync(results).find((d) => d.endsWith(`-${r.case}-${r.arm}-r${r.run}`))?.slice(0, 10) ?? new Date().toISOString().slice(0, 10)}T00:00:00.000Z`;
  track(raw, dayOf);
  process.exit(0);
}
if (!['navigator', 'bare'].includes(a.arm)) { console.error('--arm navigator|bare'); process.exit(2); }
if (!a.cases && a.order !== 'date') { console.error('--cases a,b,c or --order date'); process.exit(2); }
requireAsset('bench', need('bench'));
requireAsset('cases dir', need('cases-dir'));
requireAsset('scorer', a.scorer);
const bench = realpathSync(a.bench);
const casesDir = a['cases-dir'];
const results = path.resolve(need('results'));
const cap = a['max-cost-usd'] === undefined ? Infinity : Number(a['max-cost-usd']);
const { loadTruth, scoreFiles } = await import(pathToFileURL(a.scorer).href);

const sha = (f) => (existsSync(f) ? createHash('sha256').update(readFileSync(f)).digest('hex') : null);
const features = path.join(bench, '.ambicode/navigator/features.md');
mkdirSync(results, { recursive: true });

// The bare arm runs in a copy without .ambicode/ so nothing of the plugin's learning is visible to it.
let bareDir = null;
if (a.arm === 'bare') {
  bareDir = path.join(results, 'bare-bench');
  if (!existsSync(bareDir)) cpSync(bench, bareDir, { recursive: true, filter: (s) => path.relative(bench, s) !== '.ambicode' });
}
const cwd = bareDir ?? bench;

function promptOf(id) {
  if (a.prompts && existsSync(path.join(a.prompts, `${id}.txt`))) return readFileSync(path.join(a.prompts, `${id}.txt`), 'utf8');
  const ticket = ticketOf(readFileSync(path.join(casesDir, id, 'prompt.md'), 'utf8'));
  if (!ticket) throw new Error(`no <ticket> block in ${id}/prompt.md`);
  return ticket;
}

// Without this the bare model treats the ticket as a change request and returns no files block (7 of 7 unscorable); it is the navigator agent's output contract, nothing more.
const BARE_FORMAT = '\n\n---\nDo not change anything. Locate the files this change would touch. Final message, exactly this shape:\n\n```files\n<repo-relative path>\n```\nWhy:\n<path> - <one line>\n\nEvery path in the block is an existing tracked file, one per line.\n';

function claudeArgs() {
  const base = ['-p', '--model', MODEL, '--effort', EFFORT, '--output-format', 'json', '--max-budget-usd', a['max-budget-usd'],
    '--permission-mode', 'dontAsk', '--disallowedTools', 'Edit', 'Write', 'NotebookEdit'];
  if (a.arm === 'bare') return [...base, '--allowedTools', 'Read', 'Grep', 'Glob'];
  const cli = path.join(PLUGIN, 'scripts/ambicode.mjs');
  return [...base, '--plugin-dir', PLUGIN, '--agent', 'ambicode:navigator', '--allowedTools', 'Read', 'Grep', 'Glob', `Bash(node *${cli}* navigator structure *)`, `Bash(node *${cli}* navigator learn *)`];
}

const date = new Date().toISOString().slice(0, 10);
let spent = 0;
let lastCost = 0;
const rows = [];
for (const { case: id, run } of plan({ cases: a.cases, order: a.order, runs: Number(a.runs) })) {
  if (!mayLaunch(spent, lastCost, cap)) { console.error(`cap ${cap}: spent ${spent.toFixed(3)} + last ${lastCost.toFixed(3)} would exceed it; stopping before ${id} r${run}`); break; }
  const before = sha(features);
  const statsBefore = featuresStats(existsSync(features) ? readFileSync(features, 'utf8') : null);
  const t0 = Date.now();
  const p = spawnSync('claude', claudeArgs(), { cwd, input: a.arm === 'bare' ? promptOf(id) + BARE_FORMAT : promptOf(id), encoding: 'utf8', maxBuffer: 1 << 26 });
  const duration = Date.now() - t0;
  let out;
  try { out = JSON.parse(p.stdout); if (Array.isArray(out)) out = out.findLast((e) => e.type === 'result'); } catch { out = null; }
  if (!out) { console.error(`${id} r${run}: no JSON result (exit ${p.status}): ${(p.stderr || p.stdout).slice(0, 300)}`); break; }
  const cost = out.total_cost_usd ?? 0;
  spent += cost; lastCost = cost;

  const dir = path.join(results, `${date}-${id}-${a.arm}-r${run}`);
  mkdirSync(dir, { recursive: true });
  const answer = out.result ?? '';
  writeFileSync(path.join(dir, 'answer.txt'), answer);
  const transcript = path.join(os.homedir(), '.claude/projects', encodeProjectDir(cwd), `${out.session_id}.jsonl`);
  const tools = existsSync(transcript) ? countTools(readFileSync(transcript, 'utf8')) : null;
  if (tools) copyFileSync(transcript, path.join(dir, 'transcript.jsonl'));
  const files = filesBlock(answer);
  const scores = files ? scoreFiles(files, loadTruth(id, casesDir)) : null;
  const row = { case: id, arm: a.arm, run, cost, turns: out.num_turns, duration_ms: duration, tools, returned: files?.length ?? null, scores, learn: (tools?.learn ?? 0) > 0, features_before: statsBefore, features_after: featuresStats(existsSync(features) ? readFileSync(features, 'utf8') : null), features_sha_before: before, features_sha_after: sha(features), session_id: out.session_id };
  appendFileSync(path.join(results, 'history.jsonl'), `${JSON.stringify(row)}\n`);
  rows.push(row);
  console.error(`${id} r${run}: $${cost.toFixed(3)} ${out.num_turns} turns`);
}

if (rows.length) track(rows, () => new Date().toISOString());

const f = (x) => (x == null ? '-' : x.toFixed(3));
console.log(['case', 'arm', 'run', 'cost', 'turns', 'sec', 'Grep', 'Glob', 'Read', 'struct', 'hop', 'ret', 'fullR', 'fullP', 'navR', 'navP', 'sha=='].join('\t'));
for (const r of rows) {
  const t = r.tools ?? {};
  console.log([r.case, r.arm, r.run, r.cost.toFixed(3), r.turns, Math.round(r.duration_ms / 1000), t.Grep ?? 0, t.Glob ?? 0, t.Read ?? 0, t.structure ?? 0, t.hop ?? 0, r.returned ?? '-',
    f(r.scores?.full.recall), f(r.scores?.full.precision), f(r.scores?.nav?.recall), f(r.scores?.nav?.precision), r.features_sha_before === r.features_sha_after].join('\t'));
}
console.log(`total $${spent.toFixed(3)}`);

export function plan(args) {
  const cases = (args.order === 'date' ? DATE_ORDER : (args.cases ?? '').split(',').filter(Boolean)).map(caseId);
  const out = [];
  for (const c of cases) for (let r = 1; r <= args.runs; r++) out.push({ case: c, run: r });
  return out;
}

// The control arm of archive/evals/nav/learn-real/phase2.mjs fed the <ticket> block of the case's prompt.md.
export const ticketOf = (promptMd) => /<ticket>\n([\s\S]*?)\n<\/ticket>/.exec(promptMd)?.[1] ?? null;

const mean = (xs) => (xs.length ? xs.reduce((s, x) => s + x, 0) / xs.length : null);
const r3 = (x) => (x === null ? null : Number(x.toFixed(3)));
const f1Of = (p, r) => (p === null || r === null ? null : p + r === 0 ? 0 : (2 * p * r) / (p + r));
const stat = (xs) => {
  const v = xs.filter((x) => typeof x === 'number');
  const m = mean(v);
  const sd = v.length < 2 ? null : Math.sqrt(v.reduce((s, x) => s + (x - m) ** 2, 0) / (v.length - 1));
  return { mean: r3(m), sd: r3(sd), n: v.length };
};

/**
 * One evals/history.jsonl row per case and arm from the runner's raw rows (same shape as track.mjs rowsOf).
 * The navigator arm is `plugin` and `bare` stays `bare`, the two arms history.md compares; `suite` marks the rows.
 * The score is full recall, so `lift` = navigator − bare is a recall difference.
 */
export function trackedRows(raw, { at, model, effort, plugin }) {
  const groups = new Map();
  for (const r of raw) {
    const key = `${r.arm}:${r.case}`;
    (groups.get(key) ?? groups.set(key, []).get(key)).push(r);
  }
  return [...groups.values()].map((runs) => {
    const { case: id, arm } = runs[0];
    const recall = runs.map((r) => (r.scores ? r.scores.full.recall : 0));
    const precision = runs.map((r) => r.scores?.full.precision ?? null);
