content.content:
// Runs the suite through `claude plugin eval` and records the result in the history.
// Usage: run.mjs [--bare] [--case <glob>] [--tag <tag>] [--runs <n>] [--model <m>] [--effort <level>]
//                [--max-cost-usd <usd>] [--dry-run]
// --bare runs evals/bare/ against an empty plugin: the same requests with nothing of AMBICODE loaded.
import { spawnSync } from 'node:child_process';
import { cpSync, mkdirSync, readdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { harvest } from './context.mjs';
import { longestReport } from './chain.mjs';
import { caseOf } from './cases.mjs';
import { metricsOf } from './metrics.mjs';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

export const DEFAULTS = { model: 'claude-sonnet-5-5', effort: 'low', runs: '1', maxCostUsd: '15', concurrency: '4' };
const REPO = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..');
export const RESULTS = path.join(REPO, 'evals', 'cases', 'results');
// Outside the plugin, because the harness walks the whole target directory; .tmp/ is gitignored.
export const NAKED = path.join(REPO, '.tmp', 'naked');
// In git beside history.md, which links them: the results folder is gitignored and hidden in most views.
export const CHAINS = path.join(REPO, 'evals', 'chains');

function option(argv, name) {
  const at = argv.indexOf(name);
  return at >= 0 ? (argv[at + 1] ?? null) : null;
}

/** The harness argv and environment of one run; everything is fixed here so a history row says how to reproduce it. */
export function plan(argv, defaults = DEFAULTS) {
  const arm = argv.includes('--bare') ? 'bare' : 'plugin';
  const model = option(argv, '--model') ?? defaults.model;
  const effort = option(argv, '--effort') ?? defaults.effort;
  const result = path.join(RESULTS, `${arm}.json`);
  const out = [
    'plugin', 'eval', arm === 'bare' ? NAKED : REPO,
    '--eval-dir', arm === 'bare' ? 'evals/bare' : 'evals/cases',
    '--scaffold', '--trust-plugin', '--no-publish',
    // Kept so the context size can be read from each trace; harvest() deletes every sandbox afterwards.
    '--keep-temp',
    // One arm per run: a plugin case's prompt types /ambicode:<skill>, which means nothing with no plugin loaded.
    '--ablation', 'none',
    '--allow-tools', 'Bash', 'Edit', 'Write',
    '--model', model,
    '--runs', option(argv, '--runs') ?? defaults.runs,
    '-j', defaults.concurrency,
    '--max-cost-usd', option(argv, '--max-cost-usd') ?? defaults.maxCostUsd,
    '--json', result,
  ];
  for (const name of ['--case', '--tag']) {
    const value = option(argv, name);
    if (value !== null) out.push(name, value);
  }
  // The harness has no effort flag; the variable reaches the run's claude child (probed 2026-10-12: `env=[low]`).
  const env = { CLAUDE_CODE_EFFORT_LEVEL: effort };
  const track = [path.join(REPO, 'evals', 'scripts', 'track.mjs'), result, '--arm', arm, '--model', model, '--effort', effort];
  return { arm, argv: out, env, track, result };
}

/** An empty plugin holding a copy of evals/bare, with each scaffold pointed back at this repository's fixtures. */
export function buildNaked(repo = REPO, naked = NAKED) {
  rmSync(naked, { recursive: true, force: true });
  mkdirSync(path.join(naked, '.claude-plugin'), { recursive: true });
  writeFileSync(path.join(naked, '.claude-plugin', 'plugin.json'), `${JSON.stringify({ name: 'naked', version: '0.0.0', description: 'No components: the bare arm.' })}\n`);
  const target = path.join(naked, 'evals', 'bare');
  cpSync(path.join(repo, 'evals', 'bare'), target, { recursive: true });
  for (const name of readdirSync(target)) {
    const file = path.join(target, name, 'scaffold.sh');
    try {
      writeFileSync(file, readFileSync(file, 'utf8').replaceAll('$(cd "$(dirname "$0")/../../.." && pwd)', repo), { mode: 0o755 });
    } catch (error) {
      if (error.code !== 'ENOENT' && error.code !== 'ENOTDIR') throw error;
    }
  }
}

function main(argv) {
  const run = plan(argv);
  if (argv.includes('--dry-run')) {
    console.log(`${Object.entries(run.env).map(([k, v]) => `${k}=${v}`).join(' ')} claude ${run.argv.join(' ')}\nnode ${run.track.join(' ')}`);
    return 0;
  }
  mkdirSync(RESULTS, { recursive: true });
  if (run.arm === 'bare') buildNaked();
  const status = spawnSync('claude', run.argv, { stdio: 'inherit', env: { ...process.env, ...run.env } }).status;
  // Exit 1 is a case below the harness threshold (1.0) and 2 a partial result (cost ceiling): both are results and are
  // tracked (`partial` is the harness's own flag in the JSON). Anything else is a harness failure with nothing to track.
  if (![0, 1, 2].includes(status)) return status ?? 1;
  const result = JSON.parse(readFileSync(run.result, 'utf8'));
  // Per suite run: clearing one shared folder lost the traces of every earlier run (2026-10-12).
  harvest(result, path.join(RESULTS, 'traces', run.arm, String(result.startedAt ?? Date.now()).replace(/[:.]/g, '-')));
  for (const evalCase of result.cases ?? []) {
    const spec = caseOf(evalCase.name)?.metrics;
    if (spec === undefined) continue;
    for (const runs of Object.values(evalCase.arms ?? {})) for (const one of runs ?? []) if (one.trace) one.metrics = metricsOf(spec, readFileSync(one.trace, 'utf8'));
  }
  writeFileSync(run.result, `${JSON.stringify(result, null, 2)}\n`);
  const longest = longestReport(result, run.arm);
  if (longest !== null) {
    mkdirSync(CHAINS, { recursive: true });
    const file = path.join(CHAINS, `${run.arm}-longest.md`);
    writeFileSync(file, longest);
    console.log(`${longest.split('\n').slice(0, 3).join('\n')}\nchain: ${path.relative(REPO, file)}`);
  }
  const tracked = spawnSync(process.execPath, run.track, { stdio: 'inherit', cwd: REPO }).status;
  return tracked === 0 ? status : (tracked ?? 1);
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) process.exitCode = main(process.argv.slice(2));
// Static checks over the suite: every case is well-formed, and both trees match cases.mjs, before a paid run finds out.
import { describe, it } from 'node:test';
import assert from 'node:assert/strict';
import { readdirSync, readFileSync, statSync } from 'node:fs';
import path from 'node:path';
import { FIXTURES } from '../../fixtures/definitions.mjs';
import { CASES, EVALS, render } from './cases.mjs';

const ROOT = path.dirname(EVALS);
const SKILLS = readdirSync(path.join(ROOT, 'skills')).filter((name) => !name.startsWith('.'));
const FILES = render();

function onDisk(tree) {
  const out = [];
  const walk = (relative) => {
    for (const name of readdirSync(path.join(EVALS, relative))) {
      const child = `${relative}/${name}`;
      if (name === 'results' || name.startsWith('.')) continue;
      if (statSync(path.join(EVALS, child)).isDirectory()) walk(child);
      else out.push(child);
    }
  };
  walk(tree);
  return out.sort();
}

describe('skill coverage suite', () => {
  it('evals/cases and evals/bare are exactly what cases.mjs renders (run node evals/scripts/cases.mjs after editing it)', () => {
    const disk = [...onDisk('cases'), ...onDisk('bare')].sort();
    assert.deepEqual(disk, [...FILES.keys()].sort());
    for (const file of disk) assert.equal(readFileSync(path.join(EVALS, file), 'utf8'), FILES.get(file), file);
  });

  it('covers every skill with at least one case, and only skills that exist', () => {
    assert.deepEqual([...new Set(CASES.map((c) => c.name.split('-')[0]))].sort(), [...SKILLS].sort());
  });

  for (const c of CASES) {
    const skill = c.name.split('-')[0];
    it(`${c.name}: the prompt types the skill with a fixed --task slug, graders read literal paths, the fixture exists`, () => {
      assert.ok(c.prompt.startsWith(`/ambicode:${skill}`));
      const slug = /--task (\S+)/.exec(c.prompt)?.[1] ?? null;
      if (skill !== 'init') assert.ok(slug !== null, 'a route case fixes its task slug so graders can name the ledger');
      assert.ok(c.graders.length >= 4, 'at least four graders');
      assert.equal(new Set(c.graders.map((g) => g.name)).size, c.graders.length, 'grader names are unique');
      for (const grader of c.graders) {
        const file = /path: (\S+)/.exec(grader.text)?.[1];
        if (file === undefined) continue;
        assert.doesNotMatch(file, /[*?{]/, `${grader.name}: the harness resolves no globs`);
        if (file.includes('/tasks/') || file.includes('/reviews/')) assert.ok(file.includes(`/${slug}/`), `${grader.name}: ledger path uses the prompt's slug`);
      }
      assert.ok(FIXTURES.some((entry) => entry.name === c.fixture), `${c.fixture} is a fixture`);
    });

    if (c.bare === null) continue;
    it(`${c.name}: the bare arm asks the same thing with nothing of the plugin in prompt, graders or scaffold`, () => {
      assert.doesNotMatch(c.bare, /ambicode|--task|--answer|--headless/i);
      const shared = c.graders.filter((g) => g.shared);
      assert.ok(shared.length >= 2, 'at least two shared graders');
      for (const grader of shared) assert.doesNotMatch(grader.bare.text, /\.ambicode|ambicode:|Evidence/, `${grader.name} reads only what a bare run can produce`);
      assert.doesNotMatch(FILES.get(`bare/${c.name}/scaffold.sh`), /--ambicode-init/);
    });
  }
});
// The suite's single source: every case, both arms. `node evals/scripts/cases.mjs` rewrites evals/cases/ (plugin arm)
// and evals/bare/ (no plugin) from it; suite.test.mjs fails when the trees drift from this file.
//
// A grader marked `shared` judges the outcome (the answer, the code, the boundary) and runs in both arms; the rest read
// what only the plugin writes (ledger, subagents, report sections). The lift a case reports is the plugin's shared score
// minus the bare one, so only shared graders are ever compared.
import { mkdirSync, readdirSync, rmSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const y = (value) => `'${String(value).replace(/'/g, "''")}'`;

// ---------------------------------------------------------------- grader builders
// `file` is a literal path below the session directory: the harness resolves no globs in it.
const regex = (name, pattern, { match = 'contains', file = null, weight = 1 } = {}) => ({
  name,
  text: `---\ntype: regex\npattern: ${y(pattern)}\nmatch: ${match}\ntarget: ${file === null ? 'last_message' : `{ source: file, path: ${file} }`}\nweight: ${weight}\n---\n`,
});
const ledger = (name, pattern, file, options = {}) => regex(name, pattern, { file, ...options });
const tool = (name, toolName, inputMatch, { min = 1, max = null, weight = 1 } = {}) => ({
  name,
  text: `---\ntype: tool_used\ntool: ${toolName}\ninput_match: ${y(inputMatch)}\nmin: ${min}${max === null ? '' : `\nmax: ${max}`}\nweight: ${weight}\n---\n`,
});
const never = (name, toolName, inputMatch) => tool(name, toolName, inputMatch, { min: 0, max: 0 });
const exists = (name, file) => ({ name, text: `---\ntype: file_exists\npath: ${file}\nweight: 1\n---\n` });
const llm = (name, rubric, { file = null, weight = 2 } = {}) => ({
  name,
  text: `---\ntype: llm\nfocus: ${file === null ? 'last_message' : `{ source: file, path: ${file} }`}\nweight: ${weight}\n---\n\n${rubric.trim()}\n`,
});
/** Runs in both arms; `bare` replaces it in the bare arm when the plugin keeps the artefact somewhere the bare arm has none. */
const shared = (grader, bare = grader) => ({ ...grader, shared: true, bare: { ...bare, name: grader.name } });

const noEdits = [shared(never('no-edit', 'Edit', '.')), shared(never('no-write-source', 'Write', '"file_path":"[^"]*/(src|tests)/'))];
// The plan route edits its own steps/plan-body.md while it revises it (plan-reuse-2, 2026-10-17); only .ambicode/ paths are exempt.
const planNoEdits = [shared(never('no-edit', 'Edit', '"file_path":"(?![^"]*/\\.ambicode/)'), never('no-edit', 'Edit', '.')), noEdits[1]];
// Every route exit deletes steps/, so the draft is read from the Write that created it: `file_path` is the first key of a Write input.
const planBody = (slug, tail = '') => `"file_path":"[^"]*/tasks/${slug}/steps/plan-body\\.md"${tail === '' ? '' : `.*${tail}`}`;
const FIVE_FIELDS = 'Goal.*Changes.*Accept.*Checks.*Leaves out';
const noGit = shared(never('no-git-mutation', 'Bash', 'git (commit|push|stash|reset|checkout|clean|merge|rebase)'));

const T = (slug) => `repo/.ambicode/tasks/${slug}/ledger.jsonl`;
const R = (slug) => `repo/.ambicode/reviews/${slug}/ledger.jsonl`;
const DONE = (file) => ledger('route-done', '"kind":"exit"[^\\n]*"reason":"done"', file);
const REPO = 'The repository is at `repo/`.';
// The files list a case scores; both arms get the same sentence, so the list is a contract, not plugin behaviour.
