import { learnFeatures, learnSummary } from '#modules/navigator/learn';
import { openRepository } from '#platform/git/open';
import { MAX_HOOK_INPUT_BYTES } from '#types/hook';
import { AmbicodeError } from '#util/errors';
import type { CliCommand } from '../../types/cli.ts';

export const navigatorLearnCommand: CliCommand = {
  name: 'navigator learn',
  summary: 'Merge entries into navigator/features.md.',
  options: { values: ['file'], flags: ['json'], positionals: true },
  run: async (runtime, args) => {
    const { git, repositoryRoot } = await openRepository(runtime);
    const file = args.value('file');
    const input = args.positionals.length > 0 ? args.positionals.join('\n') : file !== null ? await runtime.fs.readText(file) : await runtime.stdin.read(MAX_HOOK_INPUT_BYTES);
    if (input === null) throw new AmbicodeError('bad-argument', 'entries on stdin are too large', { field: 'entries' });
    const outcome = await learnFeatures(runtime.fs, git, repositoryRoot, input);
    return { text: learnSummary(outcome), data: outcome };
  },
};
import { seedFeatures } from '#modules/navigator/seed';
import { openRepository } from '#platform/git/open';
import type { CliCommand } from '../../types/cli.ts';

export const navigatorSeedCommand: CliCommand = {
  name: 'navigator seed',
  summary: 'Write navigator/features.md from the tree; refuses if non-empty.',
  options: { flags: ['json'] },
  run: async (runtime) => {
    const { git, repositoryRoot } = await openRepository(runtime);
    const outcome = await seedFeatures(runtime.fs, git, repositoryRoot);
    return { text: `${outcome.path}: ${outcome.entries} features, ~${outcome.tokens} tokens`, data: outcome };
  },
};
