      source: 'files-block',
      relevant: ['main/app/6141.ts', 'main/[id]/page.ts'],
      allowed: ['main/assets/i18n/en.json', 'main/app/6141.spec.ts'],
    });
    assert.equal(navigatorSpec('task-fix', evalsDir), null);
  });

  it('only an explicit reset copies the seed over the persistent map', () => {
    const { root, env } = assets();
    const map = path.join(root, 'bench', 'repo', '.ambicode', 'navigator');
    mkdirSync(map, { recursive: true });
    writeFileSync(path.join(map, 'features.md'), 'learned\n');
    renderNavigator(navigatorSources(env));
    assert.equal(readFileSync(path.join(map, 'features.md'), 'utf8'), 'learned\n', 'rendering leaves the map alone');
    resetMap(env);
    assert.match(readFileSync(path.join(map, 'features.md'), 'utf8'), /^## seed/);
  });
});
