    const jobs = (args) => plan(args).argv[plan(args).argv.indexOf('-j') + 1];
    assert.equal(jobs(['--tag', 'navigator']), '1');
    assert.equal(jobs(['--bare', '--tag', 'navigator']), '1');
    assert.equal(jobs(['--tag', 'gate']), '4');
    assert.equal(jobs([]), '4');
  });

  it('a navigator case row is marked as its own suite, so the skill-coverage mean and cost leave it out', () => {
    const row = rowsOf({ cases: [{ name: 'fe-vs-438-investigate', arms: { with: [run(1, [])] } }] })[0];
    assert.equal(row.suite, 'navigator');
    assert.equal(row.version, 2, 'recall over the nav truth: not comparable with the version 1 rows of the earlier runner');
    assert.equal(rowsOf({ cases: [{ name: 'task-fix', arms: { with: [run(1, [])] } }] })[0].suite, undefined);
  });

  it('the bare arm runs evals/bare against the empty plugin and writes its own result', () => {
    const { arm, argv } = plan(['--bare', '--effort', 'medium']);
    assert.equal(arm, 'bare');
    assert.equal(argv[2], NAKED);
    assert.equal(argv[4], 'evals/bare');
    assert.match(argv[argv.indexOf('--json') + 1], /bare\.json$/);
  });

