    assert.equal(writeNavigator(empty, { NAV_BENCH: path.join(empty, 'x'), NAV_CASES: path.join(empty, 'y') }), 0);
    assert.equal(existsSync(path.join(empty, 'cases', 'navigator')), false);
  });

