const MIN_CASE_BUDGET_USD = 0.05;

/** The navigator pass: one call per case in date order, so the map copied back after a case is the next one's start; one merged result. */
export function navigatorPass(argv, deps = REAL, { track = () => 0, cases = NAVIGATOR_ORDER.map((id) => \`fe-vs-\${id}-investigate\`), report = console.log } = {}) {
  const total = Number(option(argv, '--max-cost-usd') ?? DEFAULTS.maxCostUsd);
  const base = plan(argv);
  const parts = [];
  let spent = 0;
  let worst = 0;
  let skipped = 0;
  for (const name of cases) {
    const left = total - spent;
    if (left < MIN_CASE_BUDGET_USD) { skipped += 1; report(\`\${name} skipped: \${left.toFixed(3)} of the \${total} USD cap left\`); continue; }
    const args = [...argv];
    for (const flag of ['--case', '--max-cost-usd']) { const at = args.indexOf(flag); if (at >= 0) args.splice(at, 2); }
    const run = plan([...args, '--case', name, '--max-cost-usd', left.toFixed(3)]);
    const { status, result } = runCase(run, deps);
    if (result === null) return { status, result: mergeResults(parts, { partial: true }), skipped };
    spent += result.costUsd ?? 0;
    worst = Math.max(worst, status);
    // The rows of this case go to the history now: a pass cut off later keeps what it measured.
    const tracked = track(run);
    if (tracked !== 0) return { status: tracked, result: null, skipped };
    parts.push(result);
    // The merged file is rewritten after each case, so an interrupted pass leaves every finished case readable.
    writeFileSync(base.result, \`\${JSON.stringify(mergeResults(parts, { partial: skipped > 0 }), null, 2)}\\n\`);
  }
  if (parts.length === 0) return { status: 1, result: null, skipped };
  const result = mergeResults(parts, { partial: skipped > 0 });
  writeFileSync(base.result, \`\${JSON.stringify(result, null, 2)}\\n\`);
  return { status: skipped > 0 ? Math.max(worst, 2) : worst, result, skipped };
