/** A fake `claude`: writes a one-case result per call, and a workspace map that has one more entry than the map it started from. */
function harness({ cost = 1 } = {}) {
  const root = mkdtempSync(path.join(tmpdir(), 'run-pass-'));
  const mapDir = path.join(root, 'map');
  mkdirSync(mapDir);
  writeFileSync(path.join(mapDir, 'features.md'), '## seed\n');
  const calls = [];
  const deps = {
    results: path.join(root, 'results'),
    tracesRoot: path.join(root, 'traces'),
    sources: () => ({ mapDir }),
    harvest: () => {},
    spawn: (_cmd, args) => {
      const at = (flag) => args[args.indexOf(flag) + 1];
      const name = at('--case');
      const before = readFileSync(path.join(mapDir, 'features.md'), 'utf8');
      calls.push({ name, cap: Number(at('--max-cost-usd')), mapBefore: (before.match(/^## /gm) ?? []).length, jobs: at('-j') });
      const workspace = path.join(root, `ws-${calls.length}`);
      mkdirSync(path.join(workspace, '.ambicode', 'navigator'), { recursive: true });
      writeFileSync(path.join(workspace, '.ambicode', 'navigator', 'features.md'), `${before}## learned-${name}\n`);
      mkdirSync(deps.results, { recursive: true });
      writeFileSync(at('--json'), JSON.stringify({
        schemaVersion: 1, startedAt: `2026-01-01T00:0${calls.length}:00.000Z`, durationSeconds: 10, costUsd: cost, partial: false, suite: { caseFilter: name },
        cases: [{ name, arms: { with: [{ score: 0.5, ambicode: workspace }] }, aggregates: { score: calls.length % 2 === 0 ? 1 : 0.5, passRate: calls.length % 2 === 0 ? 1 : 0 } }],
        aggregates: {},
      }));
      return 0;
    },
  };
  return { deps, calls, mapDir };
}

describe('navigator pass', () => {
  it('runs the cases one at a time in date order, copies the map back between them and merges one results file', () => {
    const { deps, calls, mapDir } = harness();
    const tracked = [];
    const { status, result } = navigatorPass(['--tag', 'navigator', '--max-cost-usd', '50'], deps, { track: (run) => { tracked.push(JSON.parse(readFileSync(run.result, 'utf8')).cases.length); return 0; } });
    assert.equal(status, 0);
    assert.deepEqual(calls.map((c) => c.name), NAMES);
    assert.deepEqual(calls.map((c) => c.jobs), NAMES.map(() => '1'));
    assert.deepEqual(calls.map((c) => c.mapBefore), NAMES.map((_, i) => i + 1), 'each case starts from the map the previous one left');
    assert.equal((readFileSync(path.join(mapDir, 'features.md'), 'utf8').match(/^## /gm) ?? []).length, NAMES.length + 1);
    assert.deepEqual(tracked, NAMES.map(() => 1), 'each case is tracked from its own single-case result');
    const file = JSON.parse(readFileSync(path.join(deps.results, 'plugin.json'), 'utf8'));
    assert.deepEqual(file.cases.map((c) => c.name), NAMES);
    assert.equal(file.startedAt, '2026-01-01T00:01:00.000Z');
    assert.equal(file.costUsd, NAMES.length);
    assert.equal(file.durationSeconds, 10 * NAMES.length);
    assert.equal(file.suite.caseFilter, null);
    assert.deepEqual(file.aggregates, { casesTotal: 10, casesPassed: 5, overallScore: 0.75, overallPassRate: 0.5 });
