const rows = readFileSync(`${EV}/history.jsonl`, 'utf8').split('\n').filter(Boolean).map((l) => JSON.parse(l));
const dirs = Object.fromEntries(readdirSync(`${EV}/cases/navigator`).map((d) => [d.replace(/^\d+-/, ''), d]));
for (const arm of ['plugin', 'bare']) {
  const old = JSON.parse(readFileSync(`${EV}/cases/results/${arm}.json.bak`, 'utf8'));
  const [lo, hi] = window[arm];
  const cases = [];
  const picked = [];
  for (const id of IDS) {
    const name = `fe-vs-${id}-investigate`;
    const row = rows.find((r) => r.arm === arm && r.case === name && r.at >= lo && r.at < hi);
    if (!row) throw new Error(`no row ${arm} ${name}`);
    picked.push(row);
    const per = row.perRun[0];
    const snap = path.join(EV, 'cases', 'results', 'traces', arm, row.at.replace(/[:.]/g, '-'));
    const trace = per.trace;
    if (!existsSync(trace)) throw new Error(`no trace ${trace}`);
    const amb = trace.replace(/\.jsonl$/, '.ambicode');
    const graders = Object.entries(row.graders).map(([n, rate]) => ({ name: n, passed: rate === 1 }));
    const prompt = `${EV}/cases/navigator/${dirs[name]}/prompt.md`;
    cases.push({
      name, dir: `evals/cases/navigator/${dirs[name]}`, source: 'mixed',
      promptMarkdown: existsSync(prompt) ? readFileSync(prompt, 'utf8') : undefined,
      runsPerCase: 1, timeoutSeconds: 300, maxTurns: 40,
      arms: { with: [{
        score: per.score, passed: row.passed, turns: row.turns, costUsd: Number((row.costUsd + row.judgeCostUsd).toFixed(4)), judgeCostUsd: row.judgeCostUsd,
        durationSeconds: row.seconds, startedAt: row.at, error: per.error,
        graders,
        context: { peak: per.contextPeak, final: row.contextFinal, calls: per.modelCalls, tools: per.toolCalls, session: per.sessionSeconds, api: per.apiSeconds, costUsd: per.costUsd },
        trace, ...(existsSync(amb) ? { ambicode: amb } : {}),
        metrics: { recall: per.recall, precision: per.precision, f1: per.f1, missed: per.missed, extra: per.extra, contract: per.contract },
      }] },
      aggregates: { score: row.score, passRate: row.passed ? 1 : 0 },
    });
  }
  const n = cases.length, passed = cases.filter((c) => c.aggregates.passRate === 1).length;
  const out = {
    schemaVersion: 1, claudeVersion: old.claudeVersion, startedAt: picked[0].at,
    durationSeconds: picked.reduce((s, r) => s + r.seconds, 0),
    costUsd: Number(cases.reduce((s, c) => s + c.arms.with[0].costUsd, 0).toFixed(4)),
    partial: false, backfilled: 'rebuilt from history.jsonl rows and kept traces (the per-case result files were overwritten by the next case); no grader explanations or case graders list',
    suite: { ...old.suite, caseFilter: null }, cases,
    aggregates: { casesTotal: n, casesPassed: passed, overallScore: cases.reduce((s, c) => s + c.aggregates.score, 0) / n, overallPassRate: passed / n },
  };
  writeFileSync(`${EV}/cases/results/${arm}.json`, `${JSON.stringify(out, null, 2)}\n`);
  console.log(arm, n, 'cases', out.startedAt, out.aggregates, out.costUsd, cases.filter((c) => !c.arms.with[0].ambicode).length, 'without ambicode');
}
