import path from 'node:path';
import { buildModuleTree, tokensOf } from '#modules/context/context';
import { harvest } from '#modules/search/harvest';
import { wordsOf } from '#modules/search/map';
import type { Git } from '#platform/git/git';
import { NAVIGATOR_FEATURES_FILE } from '#types/defaults';
import type { FileSystem } from '#types/platform/ports';
import { COMMON_NAMES } from '#types/modules/search';
import { AmbicodeError } from '#util/errors';
import { isSearchable, isTestPath } from '#util/path-classes';

/** User-set budget for the whole file (2026-10-17, was 2000), counted as chars/4 like every other context budget. */
export const FEATURES_BUDGET_TOKENS = 2500;
/** 30 x 80 = 2400 leaves the file under the budget with no trimming. */
export const MAX_FEATURES = 30;
export const ENTRY_TOKENS = 80;
const MAX_TERMS = 6;
const ABSENT = '-';

export interface FeatureEntry { feature: string; terms: string[]; files: string[]; deps: string[]; models: string[] }

const LINE = /^## ([^|]+?) \| terms: ([^|]*?) \| files: ([^|]*?) \| deps: ([^|]*?) \| models: ([^|]*)$/;
const list = (value: string): string[] => (value === ABSENT ? [] : value.split(',').map((item) => item.trim()));
const cell = (items: readonly string[]): string => (items.length === 0 ? ABSENT : items.join(','));

export function parseFeatures(text: string): FeatureEntry[] {
  return text.trimEnd().split('\n').map((line, index) => {
    const match = LINE.exec(line);
    if (match === null) throw new AmbicodeError('navigator-features-invalid', `features line ${index + 1} does not match "## <feature> | terms: | files: | deps: | models:".`, { field: NAVIGATOR_FEATURES_FILE });
    return { feature: match[1]!, terms: list(match[2]!), files: list(match[3]!), deps: list(match[4]!), models: list(match[5]!) };
  });
}

export const renderEntry = (entry: FeatureEntry): string => `## ${entry.feature} | terms: ${cell(entry.terms)} | files: ${cell(entry.files)} | deps: ${cell(entry.deps)} | models: ${cell(entry.models)}`;

/** A comma, pipe or newline in a path would split the field it sits in. */
const representable = (file: string): boolean => !/[,|\n]/.test(file);

/**
 * One feature per directory module of the source tree (the same cluster `context tree` uses, capped at MAX_FEATURES); directories under 3 files fold into the parent.
 * Terms are the words of file stems and declared names, rarest across features first: a word every feature has says nothing.
 * deps and models stay empty: no language-neutral way to read them from the tree.
 */
export function buildSeed(allFiles: readonly string[], names: ReadonlyMap<string, readonly string[]>): FeatureEntry[] {
  const files = allFiles.filter((file) => isSearchable(file) && !isTestPath(file) && representable(file));
  const { modules } = buildModuleTree(files, { roots: [], maxModules: MAX_FEATURES });
  // A file belongs to its deepest module, so a parent lists only what its submodules do not.
  const sources = new Map(modules.map((module) => [module.path, [] as string[]]));
  for (const file of [...files].sort()) {
    const owner = modules.filter((module) => file.startsWith(`${module.path}/`)).sort((a, b) => b.depth - a.depth)[0];
    if (owner !== undefined) sources.get(owner.path)!.push(file);
  }
  const wordsOfFile = (file: string): string[] => [...wordsOf(path.posix.basename(file, path.posix.extname(file))), ...(names.get(file) ?? []).flatMap(wordsOf)];
  const perModule = new Map(modules.map((module) => [module.path, wordsOfModule(sources.get(module.path)!, wordsOfFile)]));
  const spread = new Map<string, number>();
  for (const words of perModule.values()) for (const word of words.keys()) spread.set(word, (spread.get(word) ?? 0) + 1);
  const shortNames = modules.map((module) => module.path.split('/').at(-1)!);
  return modules.map((module, at) => {
    const feature = shortNames.filter((name) => name === shortNames[at]).length > 1 ? module.path : shortNames[at]!;
    const own = new Set(wordsOf(module.path));
    const terms = [...perModule.get(module.path)!]
      .filter(([word]) => !own.has(word) && word.length >= 3 && !COMMON_NAMES.has(word))
      .sort((a, b) => spread.get(a[0])! - spread.get(b[0])! || b[1] - a[1] || a[0].localeCompare(b[0]))
      .slice(0, MAX_TERMS)
      .map(([word]) => word);
    const head = { feature, terms, deps: [], models: [] };
    const kept: string[] = [];
    // Files come after terms in the line, so they fill whatever the 80-token cap leaves.
    for (const file of sources.get(module.path)!) {
      if (tokensOf(`${renderEntry({ ...head, files: [...kept, file] })}\n`) > ENTRY_TOKENS) break;
      kept.push(file);
    }
    return { ...head, files: kept };
  }).filter((entry) => entry.files.length > 0).sort((a, b) => a.files[0]!.localeCompare(b.files[0]!));
}

function wordsOfModule(files: readonly string[], wordsOfFile: (file: string) => string[]): Map<string, number> {
  const counts = new Map<string, number>();
  for (const file of files) for (const word of new Set(wordsOfFile(file))) counts.set(word, (counts.get(word) ?? 0) + 1);
  return counts;
}

export interface SeedOutcome { path: string; entries: number; tokens: number }

/** An existing features.md with content holds refinements the seed cannot rebuild, so it is refused, never merged or replaced. */
export async function seedFeatures(fs: FileSystem, git: Git, root: string): Promise<SeedOutcome> {
  const target = path.join(root, NAVIGATOR_FEATURES_FILE);
  if ((await fs.exists(target)) && (await fs.readText(target)).trim() !== '') {
    throw new AmbicodeError('navigator-features-exist', `${NAVIGATOR_FEATURES_FILE} already has content; the seed does not overwrite it.`, { field: NAVIGATOR_FEATURES_FILE, details: ['Delete the file to seed again.'] });
  }
  const files = (await git.listFiles(null)).filter((file) => isSearchable(file) && !isTestPath(file));
  const names = new Map<string, string[]>();
  for (const declaration of await harvest(fs, root, files)) names.set(declaration.path, [...(names.get(declaration.path) ?? []), declaration.name]);
  const entries = buildSeed(files, names);
  const text = `${entries.map(renderEntry).join('\n')}\n`;
  const tokens = tokensOf(text);
  if (tokens > FEATURES_BUDGET_TOKENS) throw new AmbicodeError('navigator-features-too-large', `seed is ~${tokens} tokens, over ${FEATURES_BUDGET_TOKENS}.`, { field: NAVIGATOR_FEATURES_FILE });
  await fs.mkdirp(path.dirname(target));
  await fs.writeText(target, text);
  return { path: NAVIGATOR_FEATURES_FILE, entries: entries.length, tokens };
}
import path from 'node:path';
import { tokensOf } from '#modules/context/context';
import type { Git } from '#platform/git/git';
import { NAVIGATOR_FEATURES_FILE } from '#types/defaults';
import type { FileSystem } from '#types/platform/ports';
import { AmbicodeError } from '#util/errors';
import { ENTRY_TOKENS, FEATURES_BUDGET_TOKENS, MAX_FEATURES, parseFeatures, renderEntry, type FeatureEntry } from './seed.ts';

export interface LearnOutcome { added: number; merged: number; droppedPaths: number; evicted: number; entriesBefore: number; entriesAfter: number; tokensBefore: number; tokensAfter: number }

const key = (value: string): string => value.trim().toLowerCase();
const fits = (entry: FeatureEntry): boolean => tokensOf(`${renderEntry(entry)}\n`) <= ENTRY_TOKENS;
/** The seed writes `-` for both; a learned entry carries at least one of them. */
const seedOnly = (entry: FeatureEntry): boolean => entry.deps.length === 0 && entry.models.length === 0;

/** Case-insensitive union; the first spelling wins and `first` items lead, so trimming from the tail drops the oldest. */
const union = (first: readonly string[], then: readonly string[]): string[] => {
  const seen = new Set<string>();
  return [...first, ...then].filter((item) => item !== '' && !seen.has(key(item)) && seen.add(key(item)));
};

function parseProposals(text: string): FeatureEntry[] {
  if (text.trim() === '') throw new AmbicodeError('navigator-learn-invalid', 'no entries given; pass "## <feature> | terms: | files: | deps: | models:" lines as arguments or on stdin.', { field: 'entries' });
  try {
    return parseFeatures(text);
  } catch (error) {
    if (error instanceof AmbicodeError) throw new AmbicodeError('navigator-learn-invalid', error.message.replace('features line', 'entry line'), { field: 'entries' });
    throw error;
  }
}

/** Longest list loses its last item until the entry fits ENTRY_TOKENS; files keep at least one. */
function shrink(entry: FeatureEntry): FeatureEntry {
  const next = { ...entry };
  while (!fits(next)) {
    const lists = (['terms', 'deps', 'models', 'files'] as const).filter((name) => next[name].length > (name === 'files' ? 1 : 0));
    const longest = lists.sort((a, b) => next[b].length - next[a].length)[0];
    if (longest === undefined) throw new AmbicodeError('navigator-learn-invalid', `entry "${entry.feature}" is over ${ENTRY_TOKENS} tokens even with one file.`, { field: 'entries' });
    next[longest] = next[longest].slice(0, -1);
  }
  return next;
}

/**
 * Match rule: a proposal merges into the entry with the same feature name (case-insensitive); else into the learned entry sharing the most files with it; else it is added.
 * Name wins because the agent names the feature it just verified; file overlap catches the same feature under another name. Seed-only entries never absorb a proposal, they are clusters of a directory, not features.
 * Files the target now owns leave seed-only entries, and a seed entry left without files is dropped: the learned entry replaces the noisy cluster.
 * Eviction: each merged or added entry moves to the top (the last proposal ends first); while over MAX_FEATURES or the token budget the bottom seed-only entry goes, then the bottom learned one. Never-touched entries sink, so least recently useful leaves first.
 */
export async function learnFeatures(fs: FileSystem, git: Git, root: string, input: string): Promise<LearnOutcome> {
  const target = path.join(root, NAVIGATOR_FEATURES_FILE);
  const proposals = parseProposals(input);
  const existingText = (await fs.exists(target)) ? await fs.readText(target) : '';
  let entries = existingText.trim() === '' ? [] : parseFeatures(existingText);
  const tokensBefore = tokensOf(existingText);
  const entriesBefore = entries.length;
  const tracked = new Set(await git.listFiles(null));
  const outcome = { added: 0, merged: 0, droppedPaths: 0, evicted: 0 };

  for (const proposal of proposals) {
    const files = union(proposal.files, []).filter((file) => tracked.has(file));
    outcome.droppedPaths += new Set(proposal.files.map(key)).size - files.length;
    if (files.length === 0) continue;
    const owned = new Set(files.map(key));
    const overlap = (entry: FeatureEntry): number => entry.files.filter((file) => owned.has(key(file))).length;
    const byName = entries.find((entry) => key(entry.feature) === key(proposal.feature));
    const byFiles = entries.filter((entry) => !seedOnly(entry) && overlap(entry) > 0).sort((a, b) => overlap(b) - overlap(a))[0];
    const base = byName ?? byFiles;
    const merged = shrink({
      feature: base?.feature ?? proposal.feature.trim(),
      terms: union(proposal.terms, base?.terms ?? []), files: union(files, (base?.files ?? []).filter((file) => tracked.has(file))),
      deps: union(proposal.deps, base?.deps ?? []), models: union(proposal.models, base?.models ?? []),
    });
    const all = new Set(merged.files.map(key));
    entries = entries.filter((entry) => entry !== base).flatMap((entry) => {
      if (!seedOnly(entry)) return [entry];
      const rest = entry.files.filter((file) => !all.has(key(file)));
      return rest.length === 0 ? [] : [{ ...entry, files: rest }];
    });
    entries.unshift(merged);
    outcome[base === undefined ? 'added' : 'merged'] += 1;
  }

  const render = (): string => `${entries.map(renderEntry).join('\n')}\n`;
  while (entries.length > MAX_FEATURES || tokensOf(render()) > FEATURES_BUDGET_TOKENS) {
    const index = entries.findLastIndex(seedOnly) >= 0 ? entries.findLastIndex(seedOnly) : entries.length - 1;
    entries.splice(index, 1);
    outcome.evicted += 1;
  }
  const text = render();
  if (entries.length > 0 || existingText !== '') {
    await fs.mkdirp(path.dirname(target));
    const temporary = `${target}.tmp`;
    await fs.writeText(temporary, text);
    await fs.rename(temporary, target);
  }
  return { ...outcome, entriesBefore, entriesAfter: entries.length, tokensBefore, tokensAfter: tokensOf(text) };
}

export const learnSummary = (outcome: LearnOutcome): string => `navigator learn: added ${outcome.added}, merged ${outcome.merged}, dropped ${outcome.droppedPaths} paths, evicted ${outcome.evicted}; ${outcome.entriesBefore} -> ${outcome.entriesAfter} entries, ~${outcome.tokensBefore} -> ~${outcome.tokensAfter} tokens`;
