import path from 'node:path';
import { MIN_MODULE_FILES, buildDirectoryTree, isModuleSource, tokensOf } from '#modules/context/context';
import type { Git } from '#platform/git/git';
import { NAVIGATOR_FEATURES_FILE } from '#types/defaults';
import type { FileSystem } from '#types/platform/ports';
import { AmbicodeError } from '#util/errors';

/** User-set budget for the whole file (2026-10-17, was 2000), counted as chars/4 like every other context budget. */
export const FEATURES_BUDGET_TOKENS = 2500;
/** The index takes this much of it; the rest is learned entries (20 x ~80 = 1600 fits beside it). Measured 900 on a 1779-file repository. */
export const INDEX_TOKENS = 900;
/** 20 entries of ENTRY_TOKENS each fill the budget left by an index of INDEX_TOKENS. */
export const MAX_FEATURES = 20;
export const ENTRY_TOKENS = 80;
const ABSENT = '-';
export const INDEX_HEADING = '# Index';
export const LEARNED_HEADING = '# Learned';

export interface FeatureEntry { feature: string; terms: string[]; files: string[]; deps: string[]; models: string[] }

const LINE = /^## ([^|]+?) \| terms: ([^|]*?) \| files: ([^|]*?) \| deps: ([^|]*?) \| models: ([^|]*)$/;
const list = (value: string): string[] => (value === ABSENT ? [] : value.split(',').map((item) => item.trim()));
const cell = (items: readonly string[]): string => (items.length === 0 ? ABSENT : items.join(','));

export function parseFeatures(text: string): FeatureEntry[] {
  return text.trimEnd().split('\n').map((line, index) => {
    const match = LINE.exec(line);
    if (match === null) throw new AmbicodeError('navigator-features-invalid', `features line ${index + 1} does not match "## <feature> | terms: | files: | deps: | models:".`, { field: NAVIGATOR_FEATURES_FILE });
    return { feature: match[1]!, terms: list(match[2]!), files: list(match[3]!), deps: list(match[4]!), models: list(match[5]!) };
  });
}

export const renderEntry = (entry: FeatureEntry): string => `## ${entry.feature} | terms: ${cell(entry.terms)} | files: ${cell(entry.files)} | deps: ${cell(entry.deps)} | models: ${cell(entry.models)}`;

/** The index is every line before the first learned entry; a file without one (older format) is all learned entries. */
export function splitMap(text: string): { index: string; learned: string } {
  const lines = text.split('\n');
  const first = lines.findIndex((line) => line.startsWith('## '));
  const head = (first < 0 ? lines : lines.slice(0, first)).filter((line) => line.trim() !== LEARNED_HEADING && line.trim() !== '');
  const learned = first < 0 ? [] : lines.slice(first).filter((line) => line.trim() !== '');
  return { index: head.length === 0 ? '' : `${head.join('\n')}\n`, learned: learned.join('\n') };
}

export const renderMap = (index: string, entries: readonly FeatureEntry[]): string =>
  `${index}${index === '' || entries.length === 0 ? '' : `${LEARNED_HEADING}\n`}${entries.map((entry) => `${renderEntry(entry)}\n`).join('')}`;

/**
 * `<dir> (<files in its subtree>)`. A directory with two or more non-trivial child directories lists their names, so siblings are visible by name and a
 * parent exposes its sub-modules; every other directory with at least T own files follows as a bare line. T is the smallest value that fits INDEX_TOKENS.
 */
export function buildIndex(allFiles: readonly string[]): string {
  const root = buildDirectoryTree(allFiles.filter(isModuleSource).sort());
  const hierarchy: string[] = [];
  const listed = new Set<string>();
  const flat: { path: string; own: number; count: number }[] = [];
  const visit = (node: typeof root): void => {
    const kids = [...node.children.values()].filter((child) => child.count >= MIN_MODULE_FILES).sort((a, b) => (a.path < b.path ? -1 : 1));
    if (kids.length >= 2) {
      listed.add(node.path);
      hierarchy.push(`${node.path === '' ? '.' : node.path} (${node.count}) | ${kids.map((kid) => kid.path.split('/').at(-1)).join(', ')}`);
    } else if (node.path !== '') flat.push({ path: node.path, own: node.files, count: node.count });
    for (const kid of kids) visit(kid);
    for (const child of node.children.values()) if (!kids.includes(child)) visit(child);
  };
  visit(root);
  const render = (min: number): string => [INDEX_HEADING, ...hierarchy, ...flat.filter((dir) => dir.own >= min && !listed.has(dir.path)).sort((a, b) => (a.path < b.path ? -1 : 1)).map((dir) => `${dir.path} (${dir.count})`)].join('\n').concat('\n');
  let min = MIN_MODULE_FILES;
  while (tokensOf(render(min)) > INDEX_TOKENS && min <= root.count) min += 1;
  return render(min);
}

export interface SeedOutcome { path: string; lines: number; tokens: number }

/** An existing features.md with content holds learned entries the seed cannot rebuild, so it is refused, never merged or replaced. */
export async function seedFeatures(fs: FileSystem, git: Git, root: string): Promise<SeedOutcome> {
  const target = path.join(root, NAVIGATOR_FEATURES_FILE);
  if ((await fs.exists(target)) && (await fs.readText(target)).trim() !== '') {
    throw new AmbicodeError('navigator-features-exist', `${NAVIGATOR_FEATURES_FILE} already has content; the seed does not overwrite it.`, { field: NAVIGATOR_FEATURES_FILE, details: ['Delete the file to seed again.'] });
  }
  const text = buildIndex(await git.listFiles(null));
  const tokens = tokensOf(text);
  if (tokens > INDEX_TOKENS) throw new AmbicodeError('navigator-features-too-large', `index is ~${tokens} tokens, over ${INDEX_TOKENS}.`, { field: NAVIGATOR_FEATURES_FILE });
  await fs.mkdirp(path.dirname(target));
  await fs.writeText(target, text);
  return { path: NAVIGATOR_FEATURES_FILE, lines: text.trimEnd().split('\n').length - 1, tokens };
}
