import assert from 'node:assert/strict';
import { readFile, rm, writeFile, mkdir } from 'node:fs/promises';
import path from 'node:path';
import { createRuntime } from '#composition/root';
import { openRepository } from '#platform/git/open';
import { NAVIGATOR_FEATURES_FILE } from '#types/defaults';
import { tokensOf } from '#modules/context/context';
import { materialized } from '../../testing/fixtures/materialized.ts';
import { INDEX_TOKENS, buildIndex, parseFeatures, seedFeatures, splitMap } from './seed.ts';

let root: string;
before(async () => { root = await materialized('ts-app-medium'); });
after(async () => { await rm(path.dirname(root), { recursive: true, force: true }); });

const seed = async () => {
  const { git, repositoryRoot } = await openRepository(await createRuntime({ cwd: root }));
  const runtime = await createRuntime({ cwd: root });
  return seedFeatures(runtime.fs, git, repositoryRoot);
};
const featuresPath = () => path.join(root, NAVIGATOR_FEATURES_FILE);
const tree = (dir: string, count: number) => Array.from({ length: count }, (_, i) => `${dir}/file${i}.ts`);

describe('navigator seed on the ts-app-medium fixture', () => {
  it('writes an Index section naming each top-level folder and no learned entries', async () => {
    await rm(featuresPath(), { force: true });
    await seed();
    const text = await readFile(featuresPath(), 'utf8');
    assert.ok(text.startsWith('# Index\n'));
    assert.match(text, /^src \(\d+\) \| .*\bcustomers\b.*\binvoices\b.*\bpayments\b/m);
    assert.equal(splitMap(text).learned, '');
    assert.doesNotMatch(text, /^## /m);
  });

  it('gives byte-identical output on a second run', async () => {
    const first = await readFile(featuresPath());
    await rm(featuresPath());
    await seed();
    assert.ok(first.equals(await readFile(featuresPath())));
  });

  it('refuses to overwrite a file with content and leaves it untouched', async () => {
    await mkdir(path.dirname(featuresPath()), { recursive: true });
    await writeFile(featuresPath(), '## mine | terms: x | files: a.ts | deps: - | models: -\n');
    await assert.rejects(seed(), (error: { code?: string }) => error.code === 'navigator-features-exist');
    assert.equal(await readFile(featuresPath(), 'utf8'), '## mine | terms: x | files: a.ts | deps: - | models: -\n');
  });

  it('seeds over a file that is empty or only whitespace', async () => {
    await writeFile(featuresPath(), '\n  \n');
    await seed();
    assert.ok((await readFile(featuresPath(), 'utf8')).startsWith('# Index\n'));
  });
});

describe('parseFeatures', () => {
  it('rejects a line that is not in the entry format', () => {
    assert.throws(() => parseFeatures('## a | terms: x | files: y\n'), /features line 1/);
    assert.throws(() => parseFeatures('# title\n'), /features line 1/);
  });
});

describe('buildIndex', () => {
  it('lists siblings by name under their parent and exposes sub-modules of a deep branch', () => {
    const files = [...tree('app/features/alpha', 12), ...tree('app/features/beta', 9), ...tree('app/features/gamma/forms', 6), ...tree('app/features/gamma/wizard', 6), ...tree('app/shared', 4)];
    const lines = buildIndex(files).trimEnd().split('\n');
    assert.equal(lines[0], '# Index');
    assert.ok(lines.includes('app (37) | features, shared'));
    assert.ok(lines.includes('app/features (33) | alpha, beta, gamma'));
    assert.ok(lines.includes('app/features/gamma (12) | forms, wizard'));
  });

  it('adds directories with enough own files as bare lines and skips test files', () => {
    const files = [...tree('lib/a/one', 8), ...tree('lib/a/two', 8), ...tree('lib/b', 5), ...tree('lib/b/spec', 0), 'lib/b/x.test.ts', ...tree('lib/c/deep/er', 5)];
    const lines = buildIndex(files).trimEnd().split('\n');
    assert.ok(lines.includes('lib/b (5)'));
    assert.ok(lines.some((line) => line.startsWith('lib/c/deep/er (5)')));
    assert.ok(!lines.some((line) => line.includes('x.test')));
  });

  it('stays inside INDEX_TOKENS on a tree with far more directories than fit, keeping the biggest', () => {
    const files = Array.from({ length: 300 }, (_, d) => tree(`root/group${d % 10}/area-with-a-long-name-${d}`, 3 + (d % 7))).flat();
    const text = buildIndex(files);
    assert.ok(tokensOf(text) <= INDEX_TOKENS, `${tokensOf(text)} tokens`);
    assert.match(text, /^root \(\d+\) \| group0, group1/m);
  });
});
