/** One `claude plugin eval` call: harvest, map copy-back, metrics; leaves run.result holding this call's result. */
export function runCase(run, deps = REAL) {
  const status = deps.spawn('claude', run.argv, run.env);
  // Exit 1 is a case below the harness threshold (1.0) and 2 a partial result (cost ceiling): both are results and are
  // tracked (`partial` is the harness's own flag in the JSON). Anything else is a harness failure with nothing to track.
  if (![0, 1, 2].includes(status)) return { status: status ?? 1, result: null };
  const result = JSON.parse(readFileSync(run.result, 'utf8'));
  // Per suite run: clearing one shared folder lost the traces of every earlier run (2026-10-12).
  deps.harvest(result, path.join(deps.tracesRoot, run.arm, String(result.startedAt ?? Date.now()).replace(/[:.]/g, '-')));
  // The workspace map is a copy (the sandbox refuses a symlink); harvest kept the workspace's .ambicode, so carry it to the next case.
  const sources = deps.sources();
  for (const evalCase of result.cases ?? []) {
    if (sources === null || !isNavigatorCase(evalCase.name)) continue;
    for (const runs of Object.values(evalCase.arms ?? {})) for (const one of runs ?? []) {
      if (one.ambicode && !copyBackMap(path.join(one.ambicode, '.ambicode', 'navigator', 'features.md'), sources.mapDir)) console.log(`navigator map of ${evalCase.name} not copied back (missing, empty or over 30 entries)`);
    }
  }
  for (const evalCase of result.cases ?? []) {
    const spec = caseOf(evalCase.name)?.metrics;
    if (spec === undefined) continue;
    for (const runs of Object.values(evalCase.arms ?? {})) for (const one of runs ?? []) if (one.trace) one.metrics = metricsOf(spec, readFileSync(one.trace, 'utf8'));
  }
  writeFileSync(run.result, `${JSON.stringify(result, null, 2)}\n`);
  return { status, result };
}

/** The results of several single-case calls as one result file: startedAt of the first, costs and durations summed. */
export function mergeResults(parts, { partial = false } = {}) {
  const cases = parts.flatMap((part) => part.cases ?? []);
  const passed = cases.filter((one) => one.aggregates?.passRate === 1).length;
  const scores = cases.map((one) => one.aggregates?.score ?? 0);
  return {
    ...parts[0],
    durationSeconds: parts.reduce((sum, part) => sum + (part.durationSeconds ?? 0), 0),
    costUsd: parts.reduce((sum, part) => sum + (part.costUsd ?? 0), 0),
    partial: partial || parts.some((part) => part.partial === true),
    suite: { ...parts[0].suite, caseFilter: null },
    cases,
    aggregates: { casesTotal: cases.length, casesPassed: passed, overallScore: scores.length === 0 ? 0 : scores.reduce((a, b) => a + b, 0) / scores.length, overallPassRate: cases.length === 0 ? 0 : passed / cases.length },
  };
}

// A case that cannot start inside what is left of the cap would only be cut at once; the dust is not worth a call.
const MIN_CASE_BUDGET_USD = 0.05;

/** The navigator pass: one call per case in date order, so the map copied back after a case is the next one's start; one merged result. */
export function navigatorPass(argv, deps = REAL, { track = () => 0, cases = NAVIGATOR_ORDER.map((id) => `fe-vs-${id}-investigate`), report = console.log } = {}) {
  const total = Number(option(argv, '--max-cost-usd') ?? DEFAULTS.maxCostUsd);
  const base = plan(argv, DEFAULTS, deps.results);
  const parts = [];
  let spent = 0;
  let worst = 0;
  let skipped = 0;
  for (const name of cases) {
    const left = total - spent;
    if (left < MIN_CASE_BUDGET_USD) { skipped += 1; report(`${name} skipped: ${Math.max(0, left).toFixed(3)} of the ${total} USD cap left`); continue; }
    const args = [...argv];
    for (const flag of ['--case', '--max-cost-usd']) { const at = args.indexOf(flag); if (at >= 0) args.splice(at, 2); }
    const run = plan([...args, '--case', name, '--max-cost-usd', left.toFixed(3)], DEFAULTS, deps.results);
    const { status, result } = runCase(run, deps);
    if (result === null) return { status, result: mergeResults(parts, { partial: true }), skipped };
    spent += result.costUsd ?? 0;
    worst = Math.max(worst, status);
    // The rows of this case go to the history now: a pass cut off later keeps what it measured.
    const tracked = track(run);
    if (tracked !== 0) return { status: tracked, result: null, skipped };
    parts.push(result);
    // The merged file is rewritten after each case, so an interrupted pass leaves every finished case readable.
    writeFileSync(base.result, `${JSON.stringify(mergeResults(parts, { partial: skipped > 0 }), null, 2)}\n`);
  }
  if (parts.length === 0) return { status: 1, result: null, skipped };
  const result = mergeResults(parts, { partial: skipped > 0 });
  writeFileSync(base.result, `${JSON.stringify(result, null, 2)}\n`);
  return { status: skipped > 0 ? Math.max(worst, 2) : worst, result, skipped };
}

function chainOf(result, arm) {
  const longest = longestReport(result, arm);
  if (longest === null) return;
