// Navigator cases: ordinary eval cases rendered from NDA assets (a bench repository, ticket text and truth paths) that are
// not in git. `node evals/scripts/navigator-cases.mjs` writes evals/cases/navigator/ (plugin arm) and evals/bare/navigator/
// (bare arm), both gitignored. `--reset-map` copies the seed map over the persistent one; nothing else ever resets it.
// Assets: NAV_BENCH (repository), NAV_CASES (<id>/prompt.md with a <ticket> block + truth.json), NAV_MAP (persistent map
// dir, default <bench>/.ambicode/navigator), NAV_SEED (seed map, default <bench>/../features.seed.md).
import { copyFileSync, existsSync, mkdirSync, readdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const EVALS = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const REPO = path.dirname(EVALS);

// Base-commit date order of the fe-angular bench cases; the map learns from each case, so the order is part of the result.
export const NAVIGATOR_ORDER = ['438', '6141', '5948', '6292', '5967', '5164', '6404', '3571', '6406', '6086'];
export const NAVIGATOR_TAG = 'navigator';
export const isNavigatorCase = (name) => /^fe-vs-\d+-investigate$/.test(name);

// Data, not code: translations, tests, mocks and fixtures are found by reading siblings, not by navigating.
// Copied from archive/evals/nav/score.mjs, which is gitignored.
const NON_NAV = [
  /(^|\/)(i18n|locales?|translations?|lang)\//i,
  /\.(spec|test)\.[^/]+$/i,
  /(^|\/)__mocks__\//,
  /(^|\/)(mocks?|fixtures?)\//i,
  /\.(mocks?|fixtures?)\.[^/]+$/i,
];
const isNonNav = (file) => NON_NAV.some((re) => re.test(file));

// The step graders carry this weight so the case score stays within 1e-4 of recall: score = (hits + w * steps passed) / (N + w * steps).
export const STEP_WEIGHT = 0.0001;
// Measured on past runs: navigator 5 to 11 turns and 11 to 29 s, bare 6 to 28 turns and 24 to 62 s. Both arms get the bare ceiling.
const LIMITS = { max_turns: 40, timeout_seconds: 300 };
const INSTRUCTION = 'Do not change anything. Return the repository files this change would need to change or read as a ```files block at the end of your answer, one repository-relative path per line.';

const y = (value) => `'${String(value).replace(/'/g, "''")}'`;
const sq = (value) => `'${String(value).replace(/'/g, `'\\''`)}'`;
const escapeRegex = (text) => text.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

const regex = (name, pattern, { flags = '', weight = 1, arm = null, target = 'last_message' } = {}) => ({
  name,
  text: `---\ntype: regex\npattern: ${y(pattern)}\n${flags === '' ? '' : `flags: ${flags}\n`}match: contains\ntarget: ${target}\nweight: ${weight}${arm === null ? '' : `\narm: ${arm}`}\n---\n`,
});
const tool = (name, toolName, inputMatch) => ({
  name,
  text: `---\ntype: tool_used\ntool: ${toolName}\ninput_match: ${y(inputMatch)}\nmin: 1\nweight: ${STEP_WEIGHT}\narm: with-only\n---\n`,
});

/** The first ```files block, so a path only counts when the contract holds; a path named in prose does not. */
const inBlock = (file) => `\`\`\`files\\r?\\n(?:(?!\`\`\`)[\\s\\S])*?^(?:\\./)?${escapeRegex(file)}[ \\t]*\\r?$`;

const slug = (file) => path.basename(file).replace(/[^A-Za-z0-9]+/g, '-').replace(/^-|-$/g, '');

/** One case's grader files: recall over the nav truth (one grader per path) and the contract. The plugin arm adds the two steps. */
function graders(nav, plugin) {
  const out = [
    regex('files-block', '```files\\r?\\n(?:[^`\\n]+\\r?\\n)+```', { weight: STEP_WEIGHT }),
    ...nav.map((file, index) => regex(`recall-${String(index + 1).padStart(2, '0')}-${slug(file)}`, inBlock(file), { flags: 'm' })),
  ];
  // tool_used cannot see results; the trace holds learn's stdout, which only a successful run prints (learnSummary).
  if (plugin) out.push(tool('navigator-called', 'Agent', 'ambicode:navigator'), regex('learn-called', 'navigator learn: added \\d+', { weight: STEP_WEIGHT, arm: 'with-only', target: 'trace' }));
  return out;
}

function scaffold({ bench, mapDir }, plugin) {
  const link = plugin
    ? `# Plugin arm only: a real copy of the persistent map (a symlink to it is EPERM under the harness sandbox); run.mjs copies it back.
mkdir -p .ambicode/navigator
cp ${sq(path.join(mapDir, 'features.md'))} .ambicode/navigator/features.md
`
    : '';
  return `#!/bin/sh
# The session directory becomes a fresh git repository holding a copy of the bench, with no .ambicode/ of its own.
set -e
(cd ${sq(bench)} && tar cf - --exclude=./.git --exclude=./.ambicode .) | tar xf -
git init -q
git add -A
git -c user.name=eval -c user.email=eval@example.invalid commit -q -m bench
${link}`;
}

function caseFiles(full, id, nav, sources, plugin, ticket, order) {
  const name = `fe-vs-${id}-investigate`;
  const files = new Map();
  const root = `${plugin ? 'cases' : 'bare'}/navigator/${String(order + 1).padStart(2, '0')}-${name}`;
  files.set(`${root}/case.yaml`, `schema_version: "1.1"\nname: ${name}\ncontext:\n  scaffold_script: scaffold.sh\n`);
  files.set(`${root}/scaffold.sh`, scaffold(sources, plugin));
  const tools = plugin ? ['Read', 'Grep', 'Glob', 'Agent', y('Bash(node *ambicode.mjs* navigator *)')] : ['Read', 'Grep', 'Glob'];
  files.set(`${root}/prompt.md`, [
    '---',
    `name: ${name}`,
    `description: ${y('Find the files of a real ticket in a real codebase; the repository map carries over from the previous case.')}`,
    `tags: ["${NAVIGATOR_TAG}"]`,
    'runs: 1',
    `max_turns: ${LIMITS.max_turns}`,
    `timeout_seconds: ${LIMITS.timeout_seconds}`,
    `allowed_tools: [${tools.join(', ')}]`,
    '---',
    '',
    `${ticket}\n\n${INSTRUCTION}`,
    '',
  ].join('\n'));
  for (const grader of graders(nav, plugin)) files.set(`${root}/graders/${grader.name}.md`, grader.text);
  // Read back by metrics (precision and the missed files); the full truth minus the nav files is allowed, not wrong.
  if (plugin) files.set(`${root}/truth.json`, `${JSON.stringify({ name, relevant: nav, allowed: full.filter((file) => !nav.includes(file)) }, null, 2)}\n`);
  return files;
}

const ticketOf = (promptMd) => /<ticket>\n([\s\S]*?)\n<\/ticket>/.exec(promptMd)?.[1] ?? null;

/** Every file of both navigator trees keyed by its path below evals/, in the order the cases must run. */
export function renderNavigator(sources) {
  const files = new Map();
  NAVIGATOR_ORDER.forEach((id, order) => {
    const dir = path.join(sources.casesDir, `fe-vs-${id}-investigate`);
    const ticket = ticketOf(readFileSync(path.join(dir, 'prompt.md'), 'utf8'));
    const full = JSON.parse(readFileSync(path.join(dir, 'truth.json'), 'utf8')).truth;
    const nav = full.filter((file) => !isNonNav(file));
    if (ticket === null || nav.length === 0) throw new Error(`fe-vs-${id}-investigate: no <ticket> block or no navigation truth`);
    for (const plugin of [true, false]) for (const [file, text] of caseFiles(full, id, nav, sources, plugin, ticket, order)) files.set(file, text);
  });
  return files;
}

/** The asset paths, or null when this machine has no bench and cases (the NDA assets are not in git). */
export function navigatorSources(env = process.env) {
  const bench = path.resolve(env.NAV_BENCH ?? path.join(REPO, '..', 'ambicode-evals-assets', 'bench', 'fe-angular'));
  const casesDir = path.resolve(env.NAV_CASES ?? path.join(REPO, 'archive', 'evals', 'common', 'core', 'cases'));
  const complete = existsSync(path.join(bench, '.git')) && NAVIGATOR_ORDER.every((id) => existsSync(path.join(casesDir, `fe-vs-${id}-investigate`, 'truth.json')));
  if (!complete) return null;
  return { bench, casesDir, mapDir: path.resolve(env.NAV_MAP ?? path.join(bench, '.ambicode', 'navigator')), seed: path.resolve(env.NAV_SEED ?? path.join(bench, '..', 'features.seed.md')) };
}

/** Rewrites both navigator trees; leaves them absent (and says so in one line) without the assets. */
export function writeNavigator(evalsDir = EVALS, env = process.env) {
  for (const tree of ['cases', 'bare']) rmSync(path.join(evalsDir, tree, 'navigator'), { recursive: true, force: true });
  const sources = navigatorSources(env);
  if (sources === null) {
    console.log('navigator cases skipped: NAV_BENCH or NAV_CASES not found (NDA assets are not on this machine)');
    return 0;
  }
  const files = renderNavigator(sources);
  for (const [relative, text] of files) {
    const file = path.join(evalsDir, relative);
    mkdirSync(path.dirname(file), { recursive: true });
    writeFileSync(file, text, relative.endsWith('.sh') ? { mode: 0o755 } : undefined);
  }
  console.log(`${NAVIGATOR_ORDER.length} navigator cases, ${files.size} files`);
  return NAVIGATOR_ORDER.length;
}

/** Overwrites the persistent map with the seed; the only place it is reset. */
export function resetMap(env = process.env) {
  const sources = navigatorSources(env);
  if (sources === null || !existsSync(sources.seed)) throw new Error('navigator map not reset: assets or seed map not found');
  mkdirSync(sources.mapDir, { recursive: true });
  copyFileSync(sources.seed, path.join(sources.mapDir, 'features.md'));
  console.log(`navigator map reset: ${sources.seed} -> ${path.join(sources.mapDir, 'features.md')}`);
}

const MAX_MAP_ENTRIES = 30;

/** Copies a run's map back over the persistent one; only a non-empty map of at most 30 `## ` entries, so a failed learn never wipes it. */
export function copyBackMap(from, mapDir) {
  if (!existsSync(from)) return false;
  const text = readFileSync(from, 'utf8');
  const entries = (text.match(/^## /gm) ?? []).length;
  if (text.trim() === '' || entries === 0 || entries > MAX_MAP_ENTRIES) return false;
  mkdirSync(mapDir, { recursive: true });
  writeFileSync(path.join(mapDir, 'features.md'), text);
  return true;
}

/** The retrieval spec of a rendered navigator case (relevant and allowed files), or null; run.mjs scores answers with it. */
export function navigatorSpec(name, evalsDir = EVALS) {
  const root = path.join(evalsDir, 'cases', 'navigator');
  if (!isNavigatorCase(name) || !existsSync(root)) return null;
  for (const entry of readdirSync(root)) {
    const file = path.join(root, entry, 'truth.json');
    if (!existsSync(file)) continue;
    const { name: found, relevant, allowed } = JSON.parse(readFileSync(file, 'utf8'));
    if (found === name) return { source: 'files-block', relevant, allowed };
  }
  return null;
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  if (process.argv.includes('--reset-map')) resetMap();
  else writeNavigator();
}

