import fs from 'node:fs'; import path from 'node:path'; import {execSync} from 'node:child_process';
const BENCH='/Users/KillBill/Documents/projects/mine/ai/ambicode-evals-assets/bench/fe-angular';
const CASES='/Users/KillBill/Documents/projects/mine/ai/ambicode/archive/evals/common/core/cases';
const ORDER=['438','6141','5948','6292','5967','5164','6404','3571','6406','6086'];
const NON=[/(^|\/)(i18n|locales?|translations?|lang)\//i,/\.(spec|test)\.[^/]+$/i,/(^|\/)__mocks__\//,/(^|\/)(mocks?|fixtures?)\//i,/\.(mocks?|fixtures?)\.[^/]+$/i];
const all=execSync('git ls-files main',{cwd:BENCH,maxBuffer:1e8}).toString().trim().split('\n');
const src=all.filter(f=>/\.(ts|html|scss)$/.test(f));
const STOP=new Set('the and for with that this are not from into when will all new add can has have been any each its but also user users page value values per use used where shall system should must may than then them they there their which what who how out own via'.split(' '));
const toks=s=>s.replace(/([a-z])([A-Z])/g,'$1 $2').toLowerCase().split(/[^a-z0-9]+/).filter(Boolean);
const stem=t=>t.replace(/(ies)$/,'y').replace(/(es|s|ing|ed)$/,'');
const read=f=>{try{return fs.readFileSync(path.join(BENCH,f),'utf8')}catch{return null}};
const cache=new Map();const txt=f=>{if(!cache.has(f))cache.set(f,read(f)??'');return cache.get(f)};
const en=JSON.parse(read('main/assets/i18n/en.json'));
const flat=[];(function w(o,p){for(const k in o){const v=o[k];if(typeof v==='object'&&v)w(v,p?p+'.'+k:k);else flat.push([p?p+'.'+k:k,String(v)])}})(en,'');
const out={};
for(const id of ORDER){
 const d=path.join(CASES,`fe-vs-${id}-investigate`);
 const prompt=fs.readFileSync(d+'/prompt.md','utf8');const ticket=/<ticket>\n([\s\S]*?)\n<\/ticket>/.exec(prompt)[1];
 const full=JSON.parse(fs.readFileSync(d+'/truth.json','utf8')).truth;const nav=full.filter(f=>!NON.some(r=>r.test(f)));
 const tt=[...new Set(toks(ticket).filter(t=>t.length>=3&&!STOP.has(t)).map(stem))];
 // phrases
 const ph=new Set();
 for(const m of ticket.matchAll(/[“"‘]([^”"’\n]{3,60})[”"’]/g))ph.add(m[1].trim());
 for(const m of ticket.matchAll(/\*\*([^*\n]{3,50})\*\*/g))ph.add(m[1].replace(/[:*]/g,'').trim());
 for(const m of ticket.matchAll(/\b((?:[A-Z][a-z]+)(?: [A-Z][a-z]+)+)\b/g))ph.add(m[1]);
 const phr=[...ph].filter(p=>!/^FR-|^US-|^NOM-|^MA-/.test(p));
 // keys whose en value equals/contains phrase
 const keys=new Set();for(const p of phr){const lp=p.toLowerCase();for(const [k,v] of flat){if(v.toLowerCase()===lp)keys.add(k)}}
 // df per token
 const df={},dfTruth={};
 for(const t of tt){df[t]=all.filter(f=>toks(f).map(stem).includes(t)).length;dfTruth[t]=nav.filter(f=>toks(f).map(stem).includes(t)).length}
 // classify
 const res=nav.map(f=>{
  const parts=f.split('/');const dirs=parts.slice(1,-1);const base=parts.at(-1);
  const dt=new Set(dirs.flatMap(toks).map(stem));const ft=new Set(toks(base.replace(/\.[^.]*$/,'')).map(stem));
  const n1=tt.filter(t=>dt.has(t)&&df[t]<2500);const n2=tt.filter(t=>ft.has(t));
  const c=[];const T=txt(f).toLowerCase();
  if(T&&!/\.(png)$/.test(f)){for(const p of phr)if(p.length>=4&&T.includes(p.toLowerCase()))c.push(p);for(const k of keys){const last=k;if(T.includes(`'${k}'`)||T.includes(`"${k}"`)||T.includes(k))c.push('key:'+k)}}
  return {f,exists:fs.existsSync(path.join(BENCH,f)),n1,n2,c:[...new Set(c)]};
 });
 out[id]={ticketLen:ticket.length,tt,df,dfTruth,phr,nkeys:keys.size,res,nonNav:full.length-nav.length};
}
fs.writeFileSync('/tmp/anat/out.json',JSON.stringify(out,null,1));
for(const id of ORDER){const o=out[id];console.log('==',id,'files',o.res.length,'missing',o.res.filter(r=>!r.exists).length,'phr',o.phr.slice(0,25).join(' | '));
 for(const r of o.res)console.log((r.exists?' ':'!'),r.f.replace('main/','').slice(-95).padEnd(95),'N1:'+r.n1.join(','),'N2:'+r.n2.join(','),'C:'+r.c.slice(0,3).join(','))}
EOF
