     1	import path from 'node:path';
     2	import { MIN_MODULE_FILES, buildDirectoryTree, isModuleSource, tokensOf } from '#modules/context/context';
     3	import type { Git } from '#platform/git/git';
     4	import { NAVIGATOR_FEATURES_FILE } from '#types/defaults';
     5	import type { FileSystem } from '#types/platform/ports';
     6	import { AmbicodeError } from '#util/errors';
     7	
     8	/** User-set budget for the whole file (2026-10-17, was 2000), counted as chars/4 like every other context budget. */
     9	export const FEATURES_BUDGET_TOKENS = 2500;
    10	/** The index takes this much of it; the rest is learned entries (20 x ~80 = 1600 fits beside it). Measured 900 on a 1779-file repository. */
    11	export const INDEX_TOKENS = 900;
    12	/** 20 entries of ENTRY_TOKENS each fill the budget left by an index of INDEX_TOKENS. */
    13	export const MAX_FEATURES = 20;
    14	/** Hierarchy share of the index: the flat lines get the rest. 600 of 900 keeps the sub-module names of the big directories and leaves room for ~15 flat lines on the bench. */
    15	const HIERARCHY_TOKENS = 600;
    16	export const ENTRY_TOKENS = 80;
    17	const ABSENT = '-';
    18	export const INDEX_HEADING = '# Index';
    19	export const LEARNED_HEADING = '# Learned';
    20	
    21	export interface FeatureEntry { feature: string; terms: string[]; files: string[]; deps: string[]; models: string[] }
    22	
    23	const LINE = /^## ([^|]+?) \| terms: ([^|]*?) \| files: ([^|]*?) \| deps: ([^|]*?) \| models: ([^|]*)$/;
    24	const list = (value: string): string[] => (value === ABSENT ? [] : value.split(',').map((item) => item.trim()));
    25	const cell = (items: readonly string[]): string => (items.length === 0 ? ABSENT : items.join(','));
    26	
    27	export function parseFeatures(text: string): FeatureEntry[] {
    28	  return text.trimEnd().split('\n').map((line, index) => {
    29	    const match = LINE.exec(line);
    30	    if (match === null) throw new AmbicodeError('navigator-features-invalid', `features line ${index + 1} does not match "## <feature> | terms: | files: | deps: | models:".`, { field: NAVIGATOR_FEATURES_FILE });
    31	    return { feature: match[1]!, terms: list(match[2]!), files: list(match[3]!), deps: list(match[4]!), models: list(match[5]!) };
    32	  });
    33	}
    34	
    35	export const renderEntry = (entry: FeatureEntry): string => `## ${entry.feature} | terms: ${cell(entry.terms)} | files: ${cell(entry.files)} | deps: ${cell(entry.deps)} | models: ${cell(entry.models)}`;
    36	
    37	/** The index is every line before the first learned entry; a file without one (older format) is all learned entries. */
    38	export function splitMap(text: string): { index: string; learned: string } {
    39	  const lines = text.split('\n');
    40	  const first = lines.findIndex((line) => line.startsWith('## '));
    41	  const head = (first < 0 ? lines : lines.slice(0, first)).filter((line) => line.trim() !== LEARNED_HEADING && line.trim() !== '');
    42	  const learned = first < 0 ? [] : lines.slice(first).filter((line) => line.trim() !== '');
    43	  return { index: head.length === 0 ? '' : `${head.join('\n')}\n`, learned: learned.join('\n') };
    44	}
    45	
    46	export const renderMap = (index: string, entries: readonly FeatureEntry[]): string =>
    47	  `${index}${index === '' || entries.length === 0 ? '' : `${LEARNED_HEADING}\n`}${entries.map((entry) => `${renderEntry(entry)}\n`).join('')}`;
    48	
    49	/**
    50	 * `<dir> (<files in its subtree>)`. A directory of at least E files with two or more non-trivial child directories lists their names, so siblings are
    51	 * visible by name and a parent exposes its sub-modules; every other directory with at least T own files follows as a bare line.
    52	 * E is the smallest value whose hierarchy fits HIERARCHY_TOKENS, then T the smallest value that fits INDEX_TOKENS.
    53	 */
    54	export function buildIndex(allFiles: readonly string[]): string {
    55	  const root = buildDirectoryTree(allFiles.filter(isModuleSource).sort());
    56	  const dirs: { node: typeof root; kids: string[] }[] = [];
    57	  const visit = (node: typeof root): void => {
    58	    const kids = [...node.children.values()].filter((child) => child.count >= MIN_MODULE_FILES).map((child) => child.path.split('/').at(-1)!).sort();
    59	    dirs.push({ node, kids });
    60	    for (const child of node.children.values()) visit(child);
    61	  };
    62	  visit(root);
    63	  const hierarchy = (min: number) => dirs.filter(({ node, kids }) => kids.length >= 2 && node.count >= min);
    64	  const lineOf = ({ node, kids }: (typeof dirs)[number]): string => `${node.path === '' ? '.' : node.path} (${node.count}) | ${kids.join(', ')}`;
    65	  const sorted = (lines: { path: string; line: string }[]): string[] => lines.sort((a, b) => (a.path < b.path ? -1 : 1)).map(({ line }) => line);
    66	  const render = (expand: number, bare: number): string => {
    67	    const listed = hierarchy(expand);
    68	    const taken = new Set(listed.map(({ node }) => node.path));
    69	    const flat = dirs.filter(({ node }) => node.path !== '' && node.files >= bare && !taken.has(node.path));
    70	    return [INDEX_HEADING, ...sorted([...listed.map((dir) => ({ path: dir.node.path, line: lineOf(dir) })), ...flat.map(({ node }) => ({ path: node.path, line: `${node.path} (${node.count})` }))])].join('\n').concat('\n');
    71	  };
    72	  let expand = MIN_MODULE_FILES;
    73	  while (tokensOf(render(expand, Infinity)) > HIERARCHY_TOKENS && expand <= root.count) expand += 1;
    74	  let bare = MIN_MODULE_FILES;
    75	  while (tokensOf(render(expand, bare)) > INDEX_TOKENS && bare <= root.count) bare += 1;
    76	  return render(expand, bare);
    77	}
    78	
