const { files, imports, split } = await import('./lib.mjs');
const { buildModuleTree, isModuleSource, MIN_MODULE_FILES } = await import('#modules/context/context');
const { harvest } = await import('#modules/search/harvest');
const { nodeFileSystem } = await import('#platform/ports/filesystem');
const cand = files.filter(isModuleSource);
const tree = buildModuleTree(cand, { roots: [''], maxModules: 1e9, minFiles: MIN_MODULE_FILES });
const mods = tree.modules.map((m) => m.path).sort((a, b) => b.length - a.length);
const moduleOf = (f) => mods.find((m) => f.startsWith(m + '/')) ?? null;
const decls = await harvest(nodeFileSystem, repo, cand);
const declsBy = new Map();
for (const d of decls) (declsBy.get(d.path) ?? declsBy.set(d.path, []).get(d.path)).push(d.name);
const wordsOf = (f) => new Set([...split(path.posix.basename(f).replace(/\.[^.]+$/, '')), ...(declsBy.get(f) ?? []).flatMap(split)].filter((w) => w.length >= 3));
const df = new Map(), own = new Map();
for (const f of cand) {
  const ws = wordsOf(f);
  for (const w of ws) df.set(w, (df.get(w) ?? 0) + 1);
  const m = moduleOf(f); if (m === null) continue;
  const mm = own.get(m) ?? own.set(m, new Map()).get(m);
  for (const w of ws) mm.set(w, (mm.get(w) ?? 0) + 1);
}
const maxDf = Math.max(2, Math.floor(frac * cand.length));
const edges = new Map(), back = new Map();
const bump = (map, a, b) => { const x = map.get(a) ?? map.set(a, new Map()).get(a); x.set(b, (x.get(b) ?? 0) + 1); };
for (const [f, set] of imports) { const a = moduleOf(f); if (a === null) continue; for (const t of set) { const b = moduleOf(t); if (b === null || b === a) continue; bump(edges, a, b); bump(back, b, a); } }
const list = (map, m) => {
  const e = [...(map.get(m) ?? [])].sort((x, y) => y[1] - x[1] || (x[0] < y[0] ? -1 : 1)).slice(0, 5).map(([d]) => d);
  if (e.length === 0) return '-';
  if (e.length === 1) return e[0];
  const segs = e.map((p) => p.split('/')); let k = 0;
  while (k < Math.min(...segs.map((s) => s.length)) - 1 && segs.every((s) => s[k] === segs[0][k])) k++;
  if (k === 0) return e.join(', ');
  return segs[0].slice(0, k).join('/') + '/{' + segs.map((s) => s.slice(k).join('/')).join(', ') + '}';
};
