  log(`| N=${N} files (${pct(frac)}) | P0 | ${pct(mean('cov'))} | ${pct(mean('prec'))} | ${mean('n').toFixed(0)} |`); }
log('\n## Worst false-candidate words per case (words: false candidates / total matched)\n');
for (const id of ids) { const t = new Set(truth[id]); for (const name of ['P0 plain all words', 'M1 map2 subtree']) { const per = res[name + id].per; const arr = Object.entries(per).map(([w, fs]) => [w, fs.filter((f) => !t.has(f)).length, fs.length, fs.filter((f) => t.has(f)).length]).sort((a, b) => b[1] - a[1]).slice(0, 5);
  log(`- ${id} ${name}: ` + arr.map(([w, f, n, h]) => `${w} ${f}/${n} (hits ${h})`).join('; ')); } }
log('\n## Words matching how many map lines (map2), per case\n');
for (const id of ids) log(`- ${id}: ` + words[id].map((w) => `${w}:${maps.B.filter((m) => has(m.path.toLowerCase(), w) || m.terms.some((x) => has(x, w))).length}`).join(' '));
console.log(out.join('\n'));
