const hop = (s) => { const o = new Set(s); for (const f of s) { (imports.get(f) ?? []).forEach((g) => o.add(g)); (importers.get(f) ?? []).forEach((g) => o.add(g)); } return o; };
const V = { P0: (ws) => P(ws), P1: (ws) => P(ws.slice(0, 5)), Pn: (ws) => P(ws.filter((x) => !x.generic)), C0: (ws) => C0(ws), C1: (ws) => hop(C0(ws)), 'Pn+sym': (ws) => C0(ws.filter((x) => !x.generic)), 'Pn+sym+hop': (ws) => hop(C0(ws.filter((x) => !x.generic))) };
const pct = (x) => (100 * x).toFixed(0) + '%'; const out = []; const log = (s = '') => out.push(s); const res = {};
