for (const [name, fn] of Object.entries(V)) { const cells = KS.map((k) => { const rows = ids.map((id) => score(id, fn(sets[k][id]))); res[name + k] = rows; const m = (f) => rows.reduce((s, r) => s + r[f], 0) / rows.length; return `${pct(m('cov'))} / ${pct(m('prec'))} / ${m('n').toFixed(0)}`; }); log(`| ${name} | ${cells.join(' | ')} |`); }
log('\n## Per case cov/prec/cands, full ctx\n'); log('| variant | ' + ids.join(' | ') + ' |'); log('|---|' + ids.map(() => '---').join('|') + '|');
for (const name of Object.keys(V)) log(`| ${name} | ` + res[name + 'full'].map((r) => `${pct(r.cov)}/${pct(r.prec)}/${r.n}`).join(' | ') + ' |');
const anyHit = (w) => matchPath(w).length > 0 || grep(w).length > 0;
log('\n## Share of words hitting ANY path or content in bench\n'); log('| set | ' + ids.join(' | ') + ' | mean |'); log('|---|' + ids.map(() => '---').join('|') + '|---|');
for (const k of KS) { const sh = ids.map((id) => sets[k][id].filter((x) => anyHit(x.w)).length / sets[k][id].length); log(`| ${k} | ` + sh.map(pct).join(' | ') + ` | ${pct(sh.reduce((a, b) => a + b, 0) / sh.length)} |`); }
log('\n## Full ctx per-word (hits in truth / false / total; [content] = symbol matched by content; DEAD = no path or content hit)\n');
const contrib = [];
for (const id of ids) { const arr = sets.full[id].map((x) => { const sym = isSym(x.w) && matchPath(x.w).length === 0; const fs = sym ? grep(x.w) : matchPath(x.w); const h = fs.filter((f) => truth[id].has(f)).length; contrib.push([h, id, x.raw]); const dead = !anyHit(x.w); return `${x.raw}${sym ? '[content]' : ''}${dead ? ' DEAD' : ''} ${h}/${fs.length - h}/${fs.length}`; }); log(`- ${id}: ` + arr.join('; ')); }
