1	// Navigator cases: ordinary eval cases rendered from NDA assets (a bench repository, ticket text and truth paths) that are
2	// not in git. `node evals/scripts/navigator-cases.mjs` writes evals/cases/navigator/ (plugin arm) and evals/bare/navigator/
3	// (bare arm), both gitignored. `--reset-map` copies the seed map over the persistent one; nothing else ever resets it.
4	// Assets: NAV_BENCH (repository), NAV_CASES (<id>/prompt.md with a <ticket> block + truth.json), NAV_MAP (persistent map
5	// dir, default <bench>/.ambicode/navigator), NAV_SEED (seed map, default <bench>/../features.seed.md).
6	import { copyFileSync, existsSync, mkdirSync, readdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
7	import path from 'node:path';
8	import { fileURLToPath } from 'node:url';
9	
10	const EVALS = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
11	const REPO = path.dirname(EVALS);
12	
13	// Base-commit date order of the fe-angular bench cases; the map learns from each case, so the order is part of the result.
14	export const NAVIGATOR_ORDER = ['438', '6141', '5948', '6292', '5967', '5164', '6404', '3571', '6406', '6086'];
15	export const NAVIGATOR_TAG = 'navigator';
16	export const isNavigatorCase = (name) => /^fe-vs-\d+-investigate$/.test(name);
17	
18	// Data, not code: translations, tests, mocks and fixtures are found by reading siblings, not by navigating.
19	// Copied from archive/evals/nav/score.mjs, which is gitignored.
20	const NON_NAV = [
21	  /(^|\/)(i18n|locales?|translations?|lang)\//i,
22	  /\.(spec|test)\.[^/]+$/i,
23	  /(^|\/)__mocks__\//,
24	  /(^|\/)(mocks?|fixtures?)\//i,
25	  /\.(mocks?|fixtures?)\.[^/]+$/i,
26	];
27	const isNonNav = (file) => NON_NAV.some((re) => re.test(file));
28	
29	// The step graders carry this weight so the case score stays within 1e-4 of recall: score = (hits + w * steps passed) / (N + w * steps).
30	export const STEP_WEIGHT = 0.0001;
31	// Measured on past runs: navigator 5 to 11 turns and 11 to 29 s, bare 6 to 28 turns and 24 to 62 s. Both arms get the bare ceiling.
32	const LIMITS = { max_turns: 40, timeout_seconds: 300 };
33	const INSTRUCTION = 'Do not change anything. Return the repository files this change would need to change or read as a ```files block at the end of your answer, one repository-relative path per line.';
34	
35	const y = (value) => `'${String(value).replace(/'/g, "''")}'`;
36	const sq = (value) => `'${String(value).replace(/'/g, `'\\''`)}'`;
37	const escapeRegex = (text) => text.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
38	
39	const regex = (name, pattern, { flags = '', weight = 1, arm = null, target = 'last_message' } = {}) => ({
40	  name,
41	  text: `---\ntype: regex\npattern: ${y(pattern)}\n${flags === '' ? '' : `flags: ${flags}\n`}match: contains\ntarget: ${target}\nweight: ${weight}${arm === null ? '' : `\narm: ${arm}`}\n---\n`,
42	});
43	const tool = (name, toolName, inputMatch) => ({
44	  name,
45	  text: `---\ntype: tool_used\ntool: ${toolName}\ninput_match: ${y(inputMatch)}\nmin: 1\nweight: ${STEP_WEIGHT}\narm: with-only\n---\n`,
46	});
47	
48	/** The first ```files block, so a path only counts when the contract holds; a path named in prose does not. */
49	const inBlock = (file) => `\`\`\`files\\r?\\n(?:(?!\`\`\`)[\\s\\S])*?^(?:\\./)?${escapeRegex(file)}[ \\t]*\\r?$`;
50	
51	const slug = (file) => path.basename(file).replace(/[^A-Za-z0-9]+/g, '-').replace(/^-|-$/g, '');
52	
53	/** One case's grader files: recall over the nav truth (one grader per path) and the contract. The plugin arm adds the two steps. */
54	function graders(nav, plugin) {
55	  const out = [
56	    regex('files-block', '```files\\r?\\n(?:[^`\\n]+\\r?\\n)+```', { weight: STEP_WEIGHT }),
57	    ...nav.map((file, index) => regex(`recall-${String(index + 1).padStart(2, '0')}-${slug(file)}`, inBlock(file), { flags: 'm' })),
58	  ];
59	  // tool_used cannot see results; the trace holds learn's stdout, which only a successful run prints (learnSummary).
60	  if (plugin) out.push(tool('navigator-called', 'Agent', 'ambicode:navigator'), regex('learn-called', 'navigator learn: added \\d+', { weight: STEP_WEIGHT, arm: 'with-only', target: 'trace' }));
61	  return out;
62	}
63	
64	function scaffold({ bench, mapDir }, plugin) {
65	  const link = plugin
66	    ? `# Plugin arm only: a real copy of the persistent map (a symlink to it is EPERM under the harness sandbox); run.mjs copies it back.
67	mkdir -p .ambicode/navigator
68	cp ${sq(path.join(mapDir, 'features.md'))} .ambicode/navigator/features.md
69	`
70	    : '';
71	  return `#!/bin/sh
72	# The session directory becomes a fresh git repository holding a copy of the bench, with no .ambicode/ of its own.
73	set -e
74	(cd ${sq(bench)} && tar cf - --exclude=./.git --exclude=./.ambicode .) | tar xf -
75	git init -q
76	git add -A
77	git -c user.name=eval -c user.email=eval@example.invalid commit -q -m bench
78	${link}`;
79	}
80	
81	function caseFiles(full, id, nav, sources, plugin, ticket, order) {
82	  const name = `fe-vs-${id}-investigate`;
83	  const files = new Map();
84	  const root = `${plugin ? 'cases' : 'bare'}/navigator/${String(order + 1).padStart(2, '0')}-${name}`;
85	  files.set(`${root}/case.yaml`, `schema_version: "1.1"\nname: ${name}\ncontext:\n  scaffold_script: scaffold.sh\n`);
86	  files.set(`${root}/scaffold.sh`, scaffold(sources, plugin));
87	  const tools = plugin ? ['Read', 'Grep', 'Glob', 'Agent', y('Bash(node *ambicode.mjs* navigator *)')] : ['Read', 'Grep', 'Glob'];
88	  files.set(`${root}/prompt.md`, [
89	    '---',
90	    `name: ${name}`,
91	    `description: ${y('Find the files of a real ticket in a real codebase; the repository map carries over from the previous case.')}`,
92	    `tags: ["${NAVIGATOR_TAG}"]`,
93	    'runs: 1',
94	    `max_turns: ${LIMITS.max_turns}`,
95	    `timeout_seconds: ${LIMITS.timeout_seconds}`,
96	    `allowed_tools: [${tools.join(', ')}]`,
97	    '---',
98	    '',
99	    `${ticket}\n\n${INSTRUCTION}`,
100	    '',
101	  ].join('\n'));
102	  for (const grader of graders(nav, plugin)) files.set(`${root}/graders/${grader.name}.md`, grader.text);
103	  // Read back by metrics (precision and the missed files); the full truth minus the nav files is allowed, not wrong.
104	  if (plugin) files.set(`${root}/truth.json`, `${JSON.stringify({ name, relevant: nav, allowed: full.filter((file) => !nav.includes(file)) }, null, 2)}\n`);
105	  return files;
106	}
107	
108	const ticketOf = (promptMd) => /<ticket>\n([\s\S]*?)\n<\/ticket>/.exec(promptMd)?.[1] ?? null;
109	
110	/** Every file of both navigator trees keyed by its path below evals/, in the order the cases must run. */
111	export function renderNavigator(sources) {
112	  const files = new Map();
113	  NAVIGATOR_ORDER.forEach((id, order) => {
114	    const dir = path.join(sources.casesDir, `fe-vs-${id}-investigate`);
115	    const ticket = ticketOf(readFileSync(path.join(dir, 'prompt.md'), 'utf8'));
116	    const full = JSON.parse(readFileSync(path.join(dir, 'truth.json'), 'utf8')).truth;
117	    const nav = full.filter((file) => !isNonNav(file));
118	    if (ticket === null || nav.length === 0) throw new Error(`fe-vs-${id}-investigate: no <ticket> block or no navigation truth`);
119	    for (const plugin of [true, false]) for (const [file, text] of caseFiles(full, id, nav, sources, plugin, ticket, order)) files.set(file, text);
120	  });
121	  return files;
122	}
123	
124	/** The asset paths, or null when this machine has no bench and cases (the NDA assets are not in git). */
125	export function navigatorSources(env = process.env) {
126	  const bench = path.resolve(env.NAV_BENCH ?? path.join(REPO, '..', 'ambicode-evals-assets', 'bench', 'fe-angular'));
127	  const casesDir = path.resolve(env.NAV_CASES ?? path.join(REPO, 'archive', 'evals', 'common', 'core', 'cases'));
128	  const complete = existsSync(path.join(bench, '.git')) && NAVIGATOR_ORDER.every((id) => existsSync(path.join(casesDir, `fe-vs-${id}-investigate`, 'truth.json')));
129	  if (!complete) return null;
130	  return { bench, casesDir, mapDir: path.resolve(env.NAV_MAP ?? path.join(bench, '.ambicode', 'navigator')), seed: path.resolve(env.NAV_SEED ?? path.join(bench, '..', 'features.seed.md')) };
131	}
132	
133	/** Rewrites both navigator trees; leaves them absent (and says so in one line) without the assets. */
134	export function writeNavigator(evalsDir = EVALS, env = process.env) {
135	  for (const tree of ['cases', 'bare']) rmSync(path.join(evalsDir, tree, 'navigator'), { recursive: true, force: true });
136	  const sources = navigatorSources(env);
137	  if (sources === null) {
138	    console.log('navigator cases skipped: NAV_BENCH or NAV_CASES not found (NDA assets are not on this machine)');
139	    return 0;
140	  }
141	  const files = renderNavigator(sources);
142	  for (const [relative, text] of files) {
143	    const file = path.join(evalsDir, relative);
144	    mkdirSync(path.dirname(file), { recursive: true });
145	    writeFileSync(file, text, relative.endsWith('.sh') ? { mode: 0o755 } : undefined);
146	  }
147	  console.log(`${NAVIGATOR_ORDER.length} navigator cases, ${files.size} files`);
148	  return NAVIGATOR_ORDER.length;
149	}
150	
151	/** Overwrites the persistent map with the seed; the only place it is reset. */
152	export function resetMap(env = process.env) {
153	  const sources = navigatorSources(env);
154	  if (sources === null || !existsSync(sources.seed)) throw new Error('navigator map not reset: assets or seed map not found');
155	  mkdirSync(sources.mapDir, { recursive: true });
156	  copyFileSync(sources.seed, path.join(sources.mapDir, 'features.md'));
157	  console.log(`navigator map reset: ${sources.seed} -> ${path.join(sources.mapDir, 'features.md')}`);
158	}
159	
160	const MAX_MAP_ENTRIES = 30;
161	
162	/** Copies a run's map back over the persistent one; only a non-empty map of at most 30 `## ` entries, so a failed learn never wipes it. */
163	export function copyBackMap(from, mapDir) {
164	  if (!existsSync(from)) return false;
165	  const text = readFileSync(from, 'utf8');
166	  const entries = (text.match(/^## /gm) ?? []).length;
167	  if (text.trim() === '' || entries === 0 || entries > MAX_MAP_ENTRIES) return false;
168	  mkdirSync(mapDir, { recursive: true });
169	  writeFileSync(path.join(mapDir, 'features.md'), text);
170	  return true;
171	}
172	
173	/** The retrieval spec of a rendered navigator case (relevant and allowed files), or null; run.mjs scores answers with it. */
174	export function navigatorSpec(name, evalsDir = EVALS) {
175	  const root = path.join(evalsDir, 'cases', 'navigator');
176	  if (!isNavigatorCase(name) || !existsSync(root)) return null;
177	  for (const entry of readdirSync(root)) {
178	    const file = path.join(root, entry, 'truth.json');
179	    if (!existsSync(file)) continue;
180	    const { name: found, relevant, allowed } = JSON.parse(readFileSync(file, 'utf8'));
181	    if (found === name) return { source: 'files-block', relevant, allowed };
182	  }
183	  return null;
184	}
185	
186	if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
187	  if (process.argv.includes('--reset-map')) resetMap();
188	  else writeNavigator();
189	}
