6	import { NAVIGATOR_ORDER, copyBackMap, STEP_WEIGHT, navigatorSources, navigatorSpec, renderNavigator, resetMap, writeNavigator } from './navigator-cases.mjs';
7	
8	// A made-up bench and cases dir: the real ones are NDA assets that are not in git.
9	function assets() {
