18	    writeFileSync(path.join(dir, 'truth.json'), JSON.stringify({ truth: ['main/assets/i18n/en.json', `main/app/${id}.ts`, 'main/[id]/page.ts', `main/app/${id}.spec.ts`] }));
19	  }
