24	describe('navigator cases', () => {
25	  it('without the assets nothing is rendered and nothing throws', () => {
26	    const empty = mkdtempSync(path.join(tmpdir(), 'nav-none-'));
27	    assert.equal(navigatorSources({ NAV_BENCH: path.join(empty, 'x'), NAV_CASES: path.join(empty, 'y') }), null);
28	    assert.equal(writeNavigator(empty, { NAV_BENCH: path.join(empty, 'x'), NAV_CASES: path.join(empty, 'y') }), 0);
29	    assert.equal(existsSync(path.join(empty, 'cases', 'navigator')), false);
30	  });
31	
32	  it('renders both arms in date order; the arms differ only in the map link, the tools and the two step graders', () => {
33	    const { env } = assets();
34	    const files = renderNavigator(navigatorSources(env));
35	    const dirs = (tree) => [...new Set([...files.keys()].filter((f) => f.startsWith(`${tree}/navigator/`)).map((f) => f.split('/')[2]))];
36	    assert.deepEqual(dirs('cases'), NAVIGATOR_ORDER.map((id, i) => `${String(i + 1).padStart(2, '0')}-fe-vs-${id}-investigate`));
37	    assert.deepEqual(dirs('bare'), dirs('cases'));
38	    const first = dirs('cases')[0];
39	    assert.match(files.get(`cases/navigator/${first}/scaffold.sh`), /cp '.*features\.md' \.ambicode\/navigator\/features\.md/);
40	    assert.doesNotMatch(files.get(`cases/navigator/${first}/scaffold.sh`), /ln -s/, 'a symlinked map is EPERM in the sandbox');
41	    assert.match(files.get(`cases/navigator/${first}/graders/learn-called.md`), /target: trace[\s\S]*arm: with-only/);
42	    assert.match(files.get(`cases/navigator/${first}/graders/learn-called.md`), /pattern: 'navigator learn: added/);
43	    assert.doesNotMatch(files.get(`bare/navigator/${first}/scaffold.sh`), /ln -s|\.ambicode\/navigator/);
44	    assert.match(files.get(`bare/navigator/${first}/scaffold.sh`), /--exclude=\.\/\.ambicode/, 'both arms start without a map');
45	    const prompt = (tree) => files.get(`${tree}/navigator/${first}/prompt.md`);
46	    const body = (tree) => prompt(tree).split('---\n\n')[1];
47	    assert.match(prompt('cases'), /TICKET-438/);
