51	    const graders = (tree) => [...files.keys()].filter((f) => f.startsWith(`${tree}/navigator/${first}/graders/`)).map((f) => path.basename(f, '.md'));
52	    assert.deepEqual(graders('cases').filter((g) => !graders('bare').includes(g)), ['navigator-called', 'learn-called']);
53	    assert.equal(graders('bare').filter((g) => g.startsWith('recall-')).length, 2, 'the i18n and spec files are not in the nav truth');
54	  });
55	
56	  it('recall graders match a path only inside the files block; the steps carry the step weight', () => {
57	    const { env } = assets();
58	    const files = renderNavigator(navigatorSources(env));
59	    const key = [...files.keys()].find((f) => f.includes('/graders/recall-') && f.startsWith('cases/'));
60	    const pattern = new RegExp(/pattern: '(.*)'\n/.exec(files.get(key))[1], 'm');
61	    assert.equal(pattern.test('```files\nmain/app/438.ts\n```'), true);
62	    assert.equal(pattern.test('x\n```files\nmain/other.ts\n./main/app/438.ts  \n```\nWhy:'), true);
