// Regenerates strategy/truth/<id>.txt (dev cases) from the full truth with the current navigator-cases filter.
// '# ' marks paths absent from the bench snapshot. Prints old (existing txt) -> new sizes for all 10 cases.
import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { NAVIGATOR_ORDER, isCompanion } from '../../../../../../evals/scripts/navigator-cases.mjs';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(HERE, '../../../../../..');
const BENCH = '/Users/KillBill/Documents/projects/mine/ai/ambicode-evals-assets/bench/fe-angular';
