// Scope-level navigator metric (offline). Truth scope = dirs holding >=1 truth file; answer scope = dirs of answer entries.
// usage: node scope-score.mjs  -> writes scope-scores.md next to this file.
import { readFileSync, readdirSync, writeFileSync, existsSync, statSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { scoreFiles, foundPaths } from '../../../../../../evals/scripts/metrics.mjs';
import { isCompanion } from '../../../../../../evals/scripts/navigator-cases.mjs';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const NAVD = path.resolve(HERE, '..');
const ROOT = path.resolve(HERE, '../../../../../..');
const BENCH = process.env.NAV_BENCH ?? '/Users/KillBill/Documents/projects/mine/ai/ambicode-evals-assets/bench/fe-angular';
const DEV = ['3571', '5948', '5967', '6086', '6141', '6292'];
const IDS = ['438', '6141', '5948', '6292', '5967', '5164', '6404', '3571', '6406', '6086'];

// snapshot tree (filesystem walk, no git)
const fileCount = new Map(); const dirSet = new Set(['']);
(function walk(abs, rel) {
  for (const e of readdirSync(abs, { withFileTypes: true })) {
    if (e.name === '.git' || e.name === 'node_modules' || e.name === '.ambicode') continue;
    const r = rel ? `${rel}/${e.name}` : e.name;
    if (e.isDirectory()) { dirSet.add(r); walk(path.join(abs, e.name), r); }
    else for (let d = path.posix.dirname(r); ; d = path.posix.dirname(d)) { const k = d === '.' ? '' : d; fileCount.set(k, (fileCount.get(k) ?? 0) + 1); if (k === '') break; }
  }
})(BENCH, '');

const truthOf = (id) => {
  if (DEV.includes(id)) return readFileSync(path.join(NAVD, 'strategy/truth', `${id}.txt`), 'utf8').split('\n').map((l) => l.trim()).filter((l) => l && !l.startsWith('#'));
  const dir = readdirSync(path.join(ROOT, 'evals/cases/navigator')).find((d) => d.endsWith(`fe-vs-${id}-investigate`));
  return JSON.parse(readFileSync(path.join(ROOT, 'evals/cases/navigator', dir, 'truth.json'), 'utf8')).relevant;
};
const specOf = (id) => { const dir = readdirSync(path.join(ROOT, 'evals/cases/navigator')).find((d) => d.endsWith(`fe-vs-${id}-investigate`)); return JSON.parse(readFileSync(path.join(ROOT, 'evals/cases/navigator', dir, 'truth.json'), 'utf8')); };
// file level as the grader scores it: truth.json relevant (incl. paths absent from the bench), companions dropped from the answer, allowed neither hit nor extra
const fileLevel = (id, entries) => {
  const spec = { ...specOf(id), ignore: isCompanion };
  const r = scoreFiles(spec, foundPaths(`\`\`\`files\n${entries.join('\n')}\n\`\`\``, 'files-block'));
  return { gR: r.recall ?? 0, gP: r.precision ?? 0, gF: r.f1 ?? 0 };
};
const parseBlock = (text, last) => {
  const m = [...text.matchAll(/```files[^\n]*\n([\s\S]*?)```/g)]; if (!m.length) return null;
  return (last ? m[m.length - 1] : m[0])[1].split('\n').map((l) => l.trim().replace(/^\.\//, '').split(/\s+/)[0]).filter((l) => l && !l.startsWith('#'));
};
const lastText = (file) => {
  const lines = readFileSync(file, 'utf8').trim().split('\n').map((l) => JSON.parse(l));
  const a = lines.filter((x) => x.type === 'assistant' && !x.isSidechain && x.message?.content?.some((c) => c.type === 'text'));
  return a.length ? a[a.length - 1].message.content.filter((c) => c.type === 'text').map((c) => c.text).join('\n') : '';
};
const dirOf = (p) => { const q = p.replace(/\/+$/, ''); if (dirSet.has(q)) return q; const d = path.posix.dirname(q); return d === '.' ? '' : d; };
const depth = (d) => (d === '' ? 0 : d.split('/').length);
// up(s,t): levels s sits above t, or null
const up = (s, t) => (s === t ? 0 : s === '' ? depth(t) : t.startsWith(`${s}/`) ? depth(t) - depth(s) : null);

export function score(truthFiles, entriesAll, id) {
  const entries = entriesAll.filter((e) => !isCompanion(e));
  const T = [...new Set(truthFiles.map((f) => f.endsWith('/') ? f.slice(0, -1) : path.posix.dirname(f) === '.' ? '' : path.posix.dirname(f)))];
  const S = [...new Set(entries.map(dirOf))];
  const out = { T: T.length, S: S.length };
  for (const k of [0, 1, 2]) {
    const rec = S.length ? T.filter((t) => S.some((s) => { const u = up(s, t); return u !== null && u <= k; })).length / T.length : 0;
    const prec = S.length ? S.filter((s) => T.some((t) => { const u = up(s, t); return (u !== null && u <= k) || up(t, s) !== null; })).length / S.length : 0;
    out[`r${k}`] = rec; out[`p${k}`] = prec; out[`f${k}`] = rec + prec ? (2 * rec * prec) / (rec + prec) : 0;
  }
  out.breadth = S.length ? S.reduce((a, s) => a + (fileCount.get(s) ?? 0), 0) / S.length : 0;
  const tf = new Set(truthFiles.filter((f) => !f.endsWith('/'))); out.fileR = entries.length && tf.size ? [...new Set(entries)].filter((e) => tf.has(e)).length / tf.size : 0; out.n = entries.length;
  return { ...out, ...fileLevel(id, entries) };
}

// runs
const runDirs = (arm, lo, hi) => readdirSync(path.join(ROOT, 'evals/cases/results/traces', arm)).filter((d) => d >= lo && d <= hi).sort();
const PASSES = { p1: ['plugin', '2026-10-17T15-43', '2026-10-17T15-49-99'], p2: ['plugin', '2026-10-17T16-27', '2026-10-17T16-34-99'], p3: ['plugin', '2026-10-17T17-06', '2026-10-17T17-31-99'],
  b1: ['bare', '2026-10-17T15-50', '2026-10-17T15-55-99'], b2: ['bare', '2026-10-17T16-35', '2026-10-17T16-41-99'] };
const rows = []; // {arm,id,...score}
for (const [arm, [kind, lo, hi]] of Object.entries(PASSES)) for (const d of runDirs(kind, lo, hi)) {
  const base = path.join(ROOT, 'evals/cases/results/traces', kind, d);
  for (const f of readdirSync(base).filter((x) => /^fe-vs-\d+-investigate-1\.jsonl$/.test(x))) {
    const id = f.match(/fe-vs-(\d+)-/)[1]; const e = parseBlock(lastText(path.join(base, f)), true) ?? [];
    rows.push({ arm, id, ...score(truthOf(id), e, id) });
  }
}
for (const [arm, dir] of [['v1', 'sim'], ['v2', 'sim2']]) for (const id of DEV) {
  const f = path.join(NAVD, 'strategy', dir, `${id}.md`); if (!existsSync(f)) continue;
  rows.push({ arm, id, ...score(truthOf(id), parseBlock(readFileSync(f, 'utf8'), false) ?? [], id) });
}

const ARMS = ['p1', 'p2', 'p3', 'b1', 'b2', 'v1', 'v2'];
const mean = (a, k) => (a.length ? a.reduce((s, r) => s + r[k], 0) / a.length : NaN);
const f2 = (x) => (Number.isNaN(x) ? '-' : x.toFixed(3));
let md = '# Scope-level scores (offline)\n\nTruth = non-# lines (paths present in the bench snapshot); dev cases from strategy/truth/*.txt, others from truth.json `relevant`. Answer = last ```files block of the main session (traces), first block (sims). gR/gP/gF1 = file level as the grader scores it (truth.json relevant incl. absent paths; companion files dropped from the answer, not counted as extra). Companion files (styles, templates, tests, mocks, stories) are excluded from the truth and dropped from the answer everywhere. File R here is exact path match against that truth (denominators differ from the grader for cases with # lines).\n\n';
const summary = (label, ids) => {
  md += `## ${label}\n\n| arm | n | R@0 | R@1 | R@2 | P@0 | P@1 | P@2 | F1@0 | F1@1 | F1@2 | breadth | answer size | file R | gR | gP | gF1 |\n|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|---|\n`;
  for (const a of ARMS) { const r = rows.filter((x) => x.arm === a && ids.includes(x.id)); if (!r.length) continue;
    md += `| ${a} | ${r.length} | ${['r0', 'r1', 'r2', 'p0', 'p1', 'p2', 'f0', 'f1', 'f2'].map((k) => f2(mean(r, k))).join(' | ')} | ${mean(r, 'breadth').toFixed(0)} | ${mean(r, 'n').toFixed(1)} | ${f2(mean(r, 'fileR'))} | ${f2(mean(r, 'gR'))} | ${f2(mean(r, 'gP'))} | ${f2(mean(r, 'gF'))} |\n`; }
  md += '\n';
};
summary('All 10 cases', IDS); summary('Dev 6 cases', DEV);
md += '## Per case x run (k=1; T = truth dirs, S = answer dirs)\n\n| case | arm | T | S | R@1 | P@1 | F1@1 | R@0 | R@2 | breadth | file R |\n|---|---|---|---|---|---|---|---|---|---|---|\n';
for (const id of IDS) for (const a of ARMS) for (const r of rows.filter((x) => x.id === id && x.arm === a))
  md += `| ${id} | ${a} | ${r.T} | ${r.S} | ${f2(r.r1)} | ${f2(r.p1)} | ${f2(r.f1)} | ${f2(r.r0)} | ${f2(r.r2)} | ${r.breadth.toFixed(0)} | ${f2(r.fileR)} |\n`;
md += '\n## p3 vs b2, k=1\n\n| case | T | p3 R | p3 P | p3 F1 | b2 R | b2 P | b2 F1 |\n|---|---|---|---|---|---|---|---|\n';
for (const id of IDS) { const p = rows.find((x) => x.id === id && x.arm === 'p3'), b = rows.find((x) => x.id === id && x.arm === 'b2');
  md += `| ${id} | ${p?.T} | ${f2(p?.r1)} | ${f2(p?.p1)} | ${f2(p?.f1)} | ${f2(b?.r1)} | ${f2(b?.p1)} | ${f2(b?.f1)} |\n`; }
writeFileSync(path.join(HERE, 'scope-scores.md'), md);
console.log(md.split('## Per case')[0]);
