import path from 'node:path';
import { harvest } from '#modules/search/harvest';
import type { FileSystem } from '#types/platform/ports';
import { AmbicodeError } from '#util/errors';

/** Design cap (01-design.md, step d): about what a model reads in one tool result without paging. */
export const STRUCTURE_LIMIT_BYTES = 6144;
const MAX_EXPORTS_PER_FILE = 25;
const MAX_NAMES = 12;
const INDEX_NAMES = ['index', 'mod', '__init__'];

export interface ImportRef { spec: string; names: string[]; resolved: string | null }

// `import {a} from 'x'`, `export * from 'x'`, `import 'x'`, `require('x')`, `import('x')`; the clause may span lines.
const FROM_IMPORT = /\b(?:import|export)\s+(?:type\s+)?([^'"`;]*?)\s*from\s*(['"])([^'"\n]+)\2/g;
const BARE_IMPORT = /\bimport\s*(['"])([^'"\n]+)\1/g;
const DESTRUCTURED_REQUIRE = /\b(?:const|let|var)\s*\{([^}]*)\}\s*=\s*require\s*\(\s*(['"])([^'"\n]+)\2\s*\)/g;
const CALL_IMPORT = /\b(?:require|import)\s*\(\s*(['"])([^'"\n]+)\1\s*\)/g;

function namesOf(clause: string): string[] {
  const names: string[] = [];
  const braces = /\{([^}]*)\}/.exec(clause);
  for (const part of (braces?.[1] ?? '').split(',')) {
    const name = part.trim().replace(/^type\s+/, '').split(/\s+as\s+/)[0]!.trim();
    if (name !== '') names.push(name);
  }
  const rest = clause.replace(/\{[^}]*\}/, '').trim();
  if (rest.includes('*')) names.push('*');
  const lead = /^([A-Za-z_$][\w$]*)\s*,?/.exec(rest.replace(/^type\s+/, ''));
  if (lead !== null && !rest.includes('*')) names.push('default');
  return names;
}

/** Module specifiers and imported names found in the text. Only the ES/CommonJS import syntax is read. */
export function importsOf(text: string): { spec: string; names: string[] }[] {
  const found = new Map<string, Set<string>>();
  const add = (spec: string, names: string[]): void => {
    const set = found.get(spec) ?? new Set<string>();
    for (const name of names) set.add(name);
    found.set(spec, set);
  };
  for (const match of text.matchAll(FROM_IMPORT)) add(match[3]!, namesOf(match[1]!));
  for (const match of text.matchAll(DESTRUCTURED_REQUIRE)) add(match[3]!, match[1]!.split(',').map((part) => part.trim().split(':')[0]!.trim()).filter((name) => /^[\w$]+$/.test(name)));
  for (const match of text.matchAll(BARE_IMPORT)) add(match[2]!, []);
  for (const match of text.matchAll(CALL_IMPORT)) add(match[2]!, []);
  return [...found].map(([spec, names]) => ({ spec, names: [...names] }));
}

/**
 * A relative specifier resolves against the importing file. Any other specifier containing "/" resolves by suffix when exactly
 * one tracked file ends with it (baseUrl and path aliases, no tsconfig read); a bare package name stays unresolved.
 */
export function resolveImport(spec: string, from: string, tracked: ReadonlySet<string>, byBase: ReadonlyMap<string, readonly string[]>): string | null {
  const relative = spec.startsWith('.');
  if (!relative && !spec.includes('/')) return null;
  const target = relative ? path.posix.normalize(path.posix.join(path.posix.dirname(from), spec)) : spec.replace(/^@[^/]*\//, '');
  if (tracked.has(target)) return target;
  const fits = (file: string, want: string): boolean => {
    const bare = file.slice(0, file.length - path.posix.extname(file).length);
    return bare === want || (!relative && bare.endsWith(`/${want}`));
  };
  const own = (byBase.get(path.posix.basename(target)) ?? []).filter((file) => fits(file, target));
  const found = own.length > 0 ? own : INDEX_NAMES.flatMap((name) => (byBase.get(name) ?? []).filter((file) => fits(file, `${target}/${name}`)));
  // `./x.component` also matches x.component.html and .scss next to the .ts; the importer's own extension wins.
  const sameKind = found.filter((file) => path.posix.extname(file) === path.posix.extname(from));
  const pool = sameKind.length > 0 ? sameKind : found;
  return pool.length === 1 || (relative && pool.length > 1) ? [...pool].sort()[0]! : null;
}

/** Tracked files indexed by name without extension, so a specifier is matched without trying every extension. */
function indexByBase(files: readonly string[]): Map<string, string[]> {
  const index = new Map<string, string[]>();
  for (const file of files) {
    const base = path.posix.basename(file, path.posix.extname(file));
    index.set(base, [...(index.get(base) ?? []), file]);
  }
  return index;
}

export interface FileStructure { path: string; exports: { signature: string; line: number }[]; imports: ImportRef[] }
export interface StructureResult { text: string; bytes: number; truncated: boolean; files: FileStructure[]; missing: string[] }

const shortNames = (names: readonly string[]): string => (names.length === 0 ? '' : `: ${names.slice(0, MAX_NAMES).join(', ')}${names.length > MAX_NAMES ? `, +${names.length - MAX_NAMES}` : ''}`);

/**
 * Exports (declaring lines) and imports of each given file, with imports resolved to tracked paths. With `hop`, instead the imports that
 * leave the given set, grouped by target file with the names imported and, where the target declares them, their signatures.
 */
export async function structure(fs: FileSystem, root: string, tracked: readonly string[], requested: readonly string[], options: { hop: boolean }): Promise<StructureResult> {
  const known = new Set(tracked);
  const wanted = [...new Set(requested.map((file) => file.replace(/^\.\//, '')))];
  const missing = wanted.filter((file) => !known.has(file));
  const paths = wanted.filter((file) => known.has(file));
  if (paths.length === 0) throw new AmbicodeError('bad-argument', `"navigator structure" found none of the given paths among tracked files${missing.length === 0 ? '' : `: ${missing.join(', ')}`}.`, { field: 'structure' });
  const byBase = indexByBase(tracked);
  const declarations = await harvest(fs, root, paths);
  const files: FileStructure[] = [];
  for (const file of paths) {
    let text = '';
    try { text = await fs.readText(path.join(root, file)); } catch { /* unreadable: no imports listed */ }
    files.push({
      path: file,
      exports: declarations.filter((declaration) => declaration.path === file).map(({ signature, line }) => ({ signature, line })),
      imports: importsOf(text).map((entry) => ({ ...entry, resolved: resolveImport(entry.spec, file, known, byBase) })),
    });
  }
  const lines = options.hop ? await hopLines(fs, root, files) : plainLines(files);
  if (missing.length > 0) lines.push(`not tracked: ${missing.join(', ')}`);
  const kept: string[] = [];
  let size = 0;
  for (const line of lines) {
    size += Buffer.byteLength(line) + 1;
    if (size > STRUCTURE_LIMIT_BYTES - 64) break;
    kept.push(line);
  }
  const truncated = kept.length < lines.length;
  const text = truncated ? `${kept.join('\n')}\n${lines.length - kept.length} more lines; pass fewer paths` : kept.join('\n');
  return { text, bytes: Buffer.byteLength(text), truncated, files, missing };
}

function plainLines(files: readonly FileStructure[]): string[] {
  return files.flatMap((file) => {
    const shown = file.exports.slice(0, MAX_EXPORTS_PER_FILE);
    const internal = file.imports.filter((entry) => entry.resolved !== null);
    const external = file.imports.filter((entry) => entry.resolved === null).map((entry) => entry.spec);
    return [
      file.path,
      ...(shown.length === 0 ? [] : ['  exports:', ...shown.map((entry) => `    ${entry.line}: ${entry.signature}`)]),
      ...(file.exports.length > shown.length ? [`    +${file.exports.length - shown.length} more`] : []),
      ...(internal.length === 0 ? [] : ['  imports:', ...internal.map((entry) => `    ${entry.resolved}${shortNames(entry.names)}`)]),
      ...(external.length === 0 ? [] : [`  external: ${external.join(', ')}`]),
    ];
  });
}

async function hopLines(fs: FileSystem, root: string, files: readonly FileStructure[]): Promise<string[]> {
  const inside = new Set(files.map((file) => file.path));
  const leaving = new Map<string, { names: Set<string>; from: Set<string> }>();
  for (const file of files) {
    for (const entry of file.imports) {
      if (entry.resolved === null || inside.has(entry.resolved)) continue;
      const slot = leaving.get(entry.resolved) ?? { names: new Set<string>(), from: new Set<string>() };
      for (const name of entry.names) slot.names.add(name);
      slot.from.add(file.path);
      leaving.set(entry.resolved, slot);
    }
  }
  const targets = [...leaving.keys()].sort();
  const declared = await harvest(fs, root, targets);
  return targets.flatMap((target) => {
    const slot = leaving.get(target)!;
    const hits = declared.filter((declaration) => declaration.path === target && slot.names.has(declaration.name));
    return [
      `${target}${shortNames([...slot.names])} (from ${[...slot.from].join(', ')})`,
      ...hits.map((declaration) => `    ${declaration.line}: ${declaration.signature}`),
    ];
  });
}

import { structure } from '#modules/navigator/structure';
import { openRepository } from '#platform/git/open';
import { AmbicodeError } from '#util/errors';
import type { CliCommand } from '../../types/cli.ts';

export const navigatorStructureCommand: CliCommand = {
  name: 'navigator structure',
  summary: 'Exports, imports, signatures of files; --hop: imports leaving the set.',
  options: { flags: ['json', 'hop'], positionals: true },
  validate: (args) => {
    if (args.positionals.length === 0) throw new AmbicodeError('bad-argument', '"navigator structure" needs at least one repository-relative file path.', { field: 'structure' });
  },
  run: async (runtime, args) => {
    const { git, repositoryRoot } = await openRepository(runtime);
    const result = await structure(runtime.fs, repositoryRoot, await git.listFiles(null), args.positionals, { hop: args.flag('hop') });
    return { text: result.text, data: result };
  },
};
