const HERE = path.dirname(new URL(import.meta.url).pathname);
const DEV = ['6141', '5967', '6292', '5948', '3571', '6086'];
const rows = []; let det = '';
for (const id of DEV) {
  const raw = parseBlock(readFileSync(path.join(HERE, '../strategy/sim-index', `${id}.md`), 'utf8'), false) ?? [];
  const tr = truthOf(id); const r = score(tr, raw, id); rows.push({ id, ...r });
  const entries = raw.filter((e) => !isCompanion(e));
  const T = [...new Set(tr.map((f) => f.endsWith('/') ? f.slice(0, -1) : path.posix.dirname(f) === '.' ? '' : path.posix.dirname(f)))];
  const S = [...new Set(entries.map(dirOf))];
  const hitS = S.filter((s) => T.some((t) => { const u = up(s, t); return u !== null && u <= 2; }));
  const miss = T.filter((t) => !S.some((s) => { const u = up(s, t); return u !== null && u <= 2; }));
  const broad = miss.filter((t) => S.some((s) => up(s, t) !== null)); const never = miss.filter((t) => !broad.includes(t));
  r.broad = broad.length; r.never = never.length; r.hitS = hitS.length;
  det += `| ${id} | ${T.length} | ${S.length} | ${hitS.length} | ${miss.length} | ${broad.length} | ${never.length} | ${r.r2.toFixed(3)} |\n`;
  det += '';
}
const m = (k) => rows.reduce((a, r) => a + r[k], 0) / rows.length;
const f = (x) => x.toFixed(3);
let md = '\n## index sim\n\nstrategy/sim-index/*.md, first ```files block, dev 6. Same metrics as above (gR/gP/gF1 = v5 grader scoreFiles with dir items and companions ignored).\n\n';
