export const AuthGuard: CanActivateFn = (): Observable<true | UrlTree> => {
  const authFacade = inject(AuthFacade);
  const router = inject(Router);
  const location = inject(Location);
  return authFacade.user$.pipe(
    map((user) => {
      if (user) {
        return true;
      }
      const navigationOptions: NavigationExtras = {};
      const destinationPath = location.path();
      if (destinationPath) {
        navigationOptions.queryParams = { destinationPath };
      }
      return router.createUrlTree(["login"], navigationOptions);
    })
  );
};
##### guards/cority.guard.ts
export const NonCorityGuard: CanMatchFn = (): Observable<true | UrlTree> => {
  const corityService = inject(CorityService);
  const orgFacade = inject(OrgFacade);
  const router = inject(Router);
  return orgFacade.org$.pipe(
    map((org) => {
      if (org && corityService.isCorityOrganization(org.externalClientApiKeyId)) {
        // Cority org, redirect to admin page
        return router.createUrlTree(["/admin"], {
          queryParamsHandling: "preserve",
        });
      } else {
        // Non-Cority org, allow access
        return true as const;
      }
    })
  );
};
