export const OktaAuthGuard: CanActivateFn = (): boolean | Observable<boolean> => {
  const subDomainService = inject(SubDomainService);
  const authFacade = inject(AuthFacade);
  const location = inject(Location);
  const subDomainName = subDomainService.subDomain;
  const destinationPath = location.path();
  if (subDomainName) {
    // Let auth facade do external redirects
    return authFacade
      .authenticateOkta$(subDomainName, destinationPath)
      .pipe(map(({ success }) => !success));
  } else {
    // Continue navigation
    return true;
  }
};
