@Injectable({ providedIn: "root" })
export class EventBusService {
  private readonly events = new Subject<EventBase>();
  public readonly events$ = this.events.asObservable();
  /**
   * A chain of 2 methods to filter events for a specific listener and event class.
   * 1. Call `eventsFor(listener)` to specify the listener - this is to filter out events that originate from the same listener.
   * 2. Call `ofClass(EventClass)` to filter events of a specific class.
   * 3. Subscribe to the resulting observable to receive events of the specified class that are not from the same listener.
   * @param listener The object that is listening for events. This is used to filter out events that originate from the same listener.
   * @param eventClass The class of the event to filter for.
   * @returns An observable that emits events of the specified class that are not from the same listener.
   */
  public eventsFor(listener: object) {
    // Return a wrapper object for further chaining
    return {
      ofClass: <T extends EventBase>(eventClass: Type<T>): Observable<T> => {
        return this.events$.pipe(
          filter((event): event is T => {
            return event.source !== listener && event instanceof eventClass;
          })
        );
      },
    };
  }
  public publish<T extends EventBase>(event: T): void {
    this.events.next(event);
  }
}

