});
export class SubdomainService {
  #getRootDomainSegmentCount() {
    const { hostname } = window.location;
    if (hostname.endsWith("localhost")) {
      // On localhost, there is only 1 segment
      return 1;
    } else {
      // On dev|staging|prod, there are 3 segments:
      // api-dev|api-staging|api.inseer.com, respectively
      return 3;
    }
  }
  getSubdomain() {
    const { hostname } = window.location;
    const hostnameSegments = hostname.split(".");
    const subdomainSegments = hostnameSegments.slice(
      0,
      -this.#getRootDomainSegmentCount()
    );
    return subdomainSegments.join(".");
  }
}
