  let remaining = (limits.maxTotalTokens - bundle.size - others.size) * 4 - unfilled.reduce((sum, text) => sum + text.length, 0) - pending.reduce((sum, item) => sum + item.base, 0);
  const need = (item: { bullets: string[] }): number => item.bullets.reduce((sum, bullet) => sum + bullet.length + 1, 0);
  pending.sort((a, b) => need(a) - need(b));
  pending.forEach((item, i) => {
    let room = Math.min(limits.maxFileTokens * 4 - item.base, Math.floor(remaining / (pending.length - i)));
    const taken: string[] = [];
    for (const bullet of item.bullets) if (bullet.length + 1 <= room) { room -= bullet.length + 1; remaining -= bullet.length + 1; taken.push(bullet); }
    bundle.set(item.note, `${[...item.before, KEY_FILES, ...taken, ...item.after].join('\n').trim()}\n`);
  });
}

