export interface IndexPlan { text: string; tokens: number; expanded: number; folders: number; deepestLevel: number; names: number; namesCovered: number; levelsByRoot: Record<string, number> }

/**
 * The index tree within \`maxTokens\`: roots start as bare folder lines, then the heaviest folder already shown (weight =
 * entity names in its whole subtree, base names when it declares none) gains its own file lines and its child folders as bare
 * lines, until the next expansion would not fit. Whole levels stop where the budget ends; on a 4.4k-file project ~60% of the
 * code sat at level 3 or deeper, so heavy deep branches must be reached before light shallow ones are widened.
 */
export function planIndex(all: readonly LevelFolder[], maxTokens: number): IndexPlan {
  const byPath = new Map(all.map((folder) => [folder.module.path, folder]));
  const own = (folder: LevelFolder): number => folder.files.reduce((sum, file) => sum + file.names.length, 0);
  const weights = new Map<string, number>();
  const weigh = (folder: LevelFolder): number => {
    const sum = own(folder) + folder.module.children.reduce((total, child) => total + weigh(byPath.get(child)!), 0);
    weights.set(folder.module.path, sum);
    return sum;
  };
  const roots = all.filter((folder) => folder.module.parent === null);
  for (const root of roots) weigh(root);
  const baseCount = (folder: LevelFolder): number => folder.files.length + folder.module.children.reduce((total, child) => total + baseCount(byPath.get(child)!), 0);
  const weightOf = (folder: LevelFolder): number => (weights.get(folder.module.path)! > 0 ? weights.get(folder.module.path)! : baseCount(folder));
  const shown = new Set(roots.map((folder) => folder.module.path));
  const expanded = new Set<string>();
  const render = (): string => {
    const lines: string[] = [];
    const walk = (folder: LevelFolder): void => {
      lines.push(...folderLines(folder, expanded.has(folder.module.path)));
      if (expanded.has(folder.module.path)) for (const child of [...folder.module.children].sort()) walk(byPath.get(child)!);
    };
    for (const root of roots) walk(root);
    return \`# Index\\n\${lines.join('\\n')}\\n\`;
  };
  for (;;) {
    const next = [...shown].filter((path) => !expanded.has(path) && (own(byPath.get(path)!) > 0 || byPath.get(path)!.module.children.length > 0))
      .sort((a, b) => weightOf(byPath.get(b)!) - weightOf(byPath.get(a)!) || (a < b ? -1 : 1))[0];
    if (next === undefined) break;
    expanded.add(next);
    if (tokensOf(render()) > maxTokens) { expanded.delete(next); break; }
    for (const child of byPath.get(next)!.module.children) shown.add(child);
  }
  const text = render();
  const shownFolders = all.filter((folder) => shown.has(folder.module.path));
  const levelsByRoot: Record<string, number> = {};
  const rootOf = (folder: LevelFolder): string => (folder.module.parent === null ? folder.module.path : rootOf(byPath.get(folder.module.parent)!));
  for (const folder of shownFolders) levelsByRoot[rootOf(folder)] = Math.max(levelsByRoot[rootOf(folder)] ?? 0, folder.level);
  return {
    text, tokens: tokensOf(text), expanded: expanded.size, folders: shownFolders.length, deepestLevel: Math.max(...shownFolders.map((folder) => folder.level)),
    names: all.reduce((sum, folder) => sum + own(folder), 0), namesCovered: all.filter((folder) => expanded.has(folder.module.path)).reduce((sum, folder) => sum + own(folder), 0), levelsByRoot,
  };
}

