/**
 * Value object that represents a score data point that:
 * - has a computer vision pre-calculated value
 * - can be overridden by the user, if they don't agree with the CV
 * - can be reset to CV generated value as needed
 */
export class CVBackedField<T> {
  private _cv: T;
  public get cv(): T {
    return this._cv;
  }
  public set cv(value: T) {
    this._cv = value ?? null;
  }

  private _userInput: T;
  public get userInput(): T {
    return this._userInput;
  }
  public set userInput(value: T) {
    this._userInput = value ?? this.cv;
  }

  public constructor(cv?: T, userInput?: T) {
    this.cv = cv;
    this.userInput = userInput;
  }

  public get hasCvValue(): boolean {
    return this.userInput === this.cv;
  }

  public get isOverriddenByUser(): boolean {
    return !this.hasCvValue;
  }

  public resetToCv(): void {
    this.userInput = this.cv;
  }
}
