const mean = (a, k) => (a.length ? a.reduce((s, r) => s + r[k], 0) / a.length : NaN);
const f2 = (x) => (Number.isNaN(x) ? '-' : x.toFixed(3));
let md = '# Scope-level scores (offline)\n\nTruth = non-# lines (paths present in the bench snapshot); dev cases from strategy/truth/*.txt, others from truth.json `relevant`. Answer = last ```files block of the main session (traces), first block (sims). gR/gP/gF1 = file level as the grader scores it (truth.json relevant incl. absent paths; companion files dropped from the answer, not counted as extra). Companion files (styles, templates, tests, mocks, stories) are excluded from the truth and dropped from the answer everywhere. File R here is exact path match against that truth (denominators differ from the grader for cases with # lines).\n\n';
const summary = (label, ids) => {
